-- Cẩm nang chọn cây (17/10/2026): chuyên mục mới "cam-nang" ở Góc chăm cây + 20 bài viết sẵn, nạp ở trạng thái NHÁP
-- (chủ shop đọc lại, sửa, bấm Đăng ở /admin/noi-dung). Ảnh trong bài là LINK ẢNH NGOÀI (Wikimedia Commons CC0 / public domain,
-- StockSnap CC0, Rawpixel public domain — không cần ghi nguồn), hiện thẳng từ máy chủ ảnh kia, không lưu trong database.
-- Bài trùng đường dẫn đã có thì bỏ qua (chạy lại không nạp trùng; bài đã xóa sẽ không tự hiện lại vì chỉ chạy một lần).
INSERT INTO "posts" ("slug", "kind", "category", "title", "excerpt", "body", "cover_file", "read_minutes", "author_name", "diseases", "tags",
  "seo_description", "status", "updated_by")
SELECT v.slug, 'article', 'cam-nang', v.title, v.excerpt, v.body, v.cover, v.minutes, 'Cây Cảnh Miền Tây', v.diseases, v.tags, v.seo, 'draft', 'Hệ thống'
FROM (VALUES
('cay-de-ban-lam-viec-de-cham', '8 cây để bàn làm việc dễ chăm, chịu máy lạnh, ít phải tưới', 'Bàn làm việc thường thiếu nắng, có máy lạnh và chủ nhân thì bận. Bài này chọn ra 8 cây để bàn sống khỏe trong điều kiện đó, kèm cách đặt, cách tưới và lỗi hay gặp để cây xanh lâu.', '[{"type": "p", "text": "Một chậu cây nhỏ trên bàn làm việc giúp góc làm việc dịu mắt hơn, nhìn đỡ khô khan sau nhiều giờ trước màn hình. Nhưng bàn làm việc là nơi khó sống với cây: ánh sáng chủ yếu từ đèn trần, máy lạnh chạy cả ngày làm không khí khô, cuối tuần không ai tưới. Chọn sai cây thì chỉ vài tuần là vàng lá, rũ ngọn."}, {"type": "p", "text": "Dưới đây là những cây vườn mình đã trồng chậu nhỏ lâu năm và thấy chịu được điều kiện văn phòng. Mỗi cây kèm cách chăm ngắn gọn để bạn chọn đúng loại hợp với chỗ ngồi của mình."}, {"type": "h2", "text": "Bàn làm việc của bạn thuộc kiểu nào?"}, {"type": "p", "text": "Trước khi chọn cây, hãy nhìn chỗ đặt chậu trong 1–2 ngày. Ba câu hỏi quan trọng nhất:"}, {"type": "list", "items": ["**Có ánh sáng tự nhiên không?** Bàn cách cửa sổ dưới 2m (dù có rèm) là \"sáng\". Bàn giữa phòng chỉ có đèn trần là \"thiếu sáng\". Phòng không cửa sổ, đèn tắt cả cuối tuần là \"rất tối\".", "**Máy lạnh thổi thẳng vào chỗ đặt cây không?** Gió lạnh thổi trực tiếp làm mép lá khô cháy, cây nào cũng sợ. Chỉ cần dời chậu khỏi luồng gió là đỡ rất nhiều.", "**Bạn tưới được mấy lần một tuần?** Người hay đi công tác nên chọn cây mọng nước, rễ củ, chịu khô được 7–10 ngày."], "ordered": false}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/FY87BH4RPX.jpg", "caption": "Một chậu cây nhỏ đặt trên bàn gỗ cạnh chồng sách — cây để bàn nên có chiều cao dưới 40cm để không che màn hình."}, {"type": "h2", "text": "1. Lưỡi hổ — bền nhất cho người bận rộn"}, {"type": "p", "text": "Nếu chỉ được chọn một cây, đó là [lưỡi hổ](/san-pham/luoi-ho). Lá mọng nước, đứng thẳng, trữ nước trong lá nên tưới 7–10 ngày một lần là đủ. Lưỡi hổ chịu được đèn văn phòng, chịu máy lạnh và gần như không bị sâu bệnh nếu không tưới quá tay."}, {"type": "p", "text": "Chọn cỡ **mini cao 20–30cm** cho bàn nhỏ, cỡ 40–50cm cho góc bàn rộng hoặc kệ cạnh bàn. Lỗi duy nhất hay gặp là tưới nhiều: đất ướt liên tục làm gốc thối mềm. Cứ đất khô hẳn mới tưới."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/Young_snake_plant_%28Sansevieria%29_in_pot.jpg/960px-Young_snake_plant_%28Sansevieria%29_in_pot.jpg", "caption": "Lưỡi hổ con trồng chậu nhỏ — lá dày, sọc ngang, rất chịu khô."}, {"type": "h2", "text": "2. Ngọc ngân — lá đốm trắng sáng cả góc bàn"}, {"type": "p", "text": "[Ngọc ngân](/san-pham/ngoc-ngan) có lá xanh loang trắng, đặt cạnh màn hình rất nổi. Cây chịu bóng râm tốt, sống được dưới đèn, chỉ cần tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần mỗi tuần. Cỡ 25–30cm vừa vặn cho bàn làm việc."}, {"type": "p", "text": "Ngọc ngân hay được chọn làm quà vì mang ý nghĩa may mắn, bình an. Lưu ý cây có nhựa gây ngứa, nên đặt xa tầm với của trẻ nhỏ và thú cưng."}, {"type": "h2", "text": "3. Phú quý và vạn lộc — sắc đỏ, hồng cho bàn làm việc"}, {"type": "p", "text": "[Phú quý](/san-pham/phu-quy) và [vạn lộc](/san-pham/van-loc) cùng họ với ngọc ngân (nhóm Aglaonema), lá dày, mép hoặc gân đỏ hồng. Hai cây này được chuộng ở bàn làm việc, quầy thu ngân vì tên gọi gắn với tài lộc. Cách chăm giống ngọc ngân: ánh sáng tán xạ, tưới khi đất mặt khô, không để đọng nước dưới đĩa."}, {"type": "p", "text": "Muốn lá giữ màu đỏ đẹp, hãy đặt cây gần nơi sáng nhất trên bàn. Cây để quá tối lâu ngày, lá mới ra sẽ nhạt màu và xanh dần."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Aglaonema_%27Pink_Star%27.webp/960px-Aglaonema_%27Pink_Star%27.webp", "caption": "Một giống Aglaonema lá hồng trồng chậu — nhóm cây này chịu bóng, hợp bàn làm việc."}, {"type": "h2", "text": "4. Lan chi — mọc nhanh, nhìn tươi mắt"}, {"type": "p", "text": "[Lan chi](/san-pham/lan-chi) (cây dây nhện) có lá sọc trắng xanh rủ xuống mềm mại, rất hợp đặt mép bàn hoặc kệ cao. Rễ củ trữ nước nên quên tưới vài ngày vẫn sống. Cây ra nhiều cây con ở đầu ngồng, cắt xuống cắm vào chậu đất là thành cây mới để tặng đồng nghiệp."}, {"type": "p", "text": "Lan chi cũng là một trong số ít cây cảnh **an toàn với chó mèo**, hợp với người làm việc tại nhà có nuôi thú cưng."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Chlorophytum_comosum_in_a_pot.jpg/960px-Chlorophytum_comosum_in_a_pot.jpg", "caption": "Lan chi trồng chậu nhỏ — lá sọc trắng, rễ củ chịu khô tốt."}, {"type": "h2", "text": "5. Ngọc bích — cây mọng nước cho bàn gần cửa sổ"}, {"type": "p", "text": "[Ngọc bích](/san-pham/ngoc-bich) (cây tiền, Crassula ovata) lá tròn mọng như đồng xu, thân hóa gỗ trông như bonsai mini. Đây là cây **cần nắng**: nên đặt ở bàn sát cửa sổ có nắng sáng 4–6 giờ mỗi ngày. Đặt giữa phòng tối, cây sẽ vươn dài, lá thưa và nhạt màu."}, {"type": "p", "text": "Bù lại, ngọc bích tưới rất ít — khoảng một lần mỗi tuần, mùa mưa còn thưa hơn. Đất khô hẳn mới tưới."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Jade_Plant%2C_Crassula_ovata_IMG_3629.jpg/960px-Jade_Plant%2C_Crassula_ovata_IMG_3629.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Ngọc bích (Crassula ovata) trồng chậu đất nung — lá tròn mọng, cần chỗ có nắng."}, {"type": "h2", "text": "6. Môn melo — cây lá lạ cho người thích sưu tầm"}, {"type": "p", "text": "[Môn melo](/san-pham/mon-melo) có lá dày, sần như da, màu xanh đậm. Cây nhỏ, phát triển chậm nên giữ dáng gọn trên bàn rất lâu. Melo cần chỗ sáng ổn định (gần cửa sổ có rèm) và không được úng nước — củ dễ thối. Tưới khoảng 1–2 lần mỗi tuần khi mặt đất khô 2–3cm."}, {"type": "h2", "text": "7. Dương xỉ mini — cho bàn có độ ẩm cao"}, {"type": "p", "text": "[Dương xỉ](/san-pham/duong-xi) cỡ mini cao 20–30cm có lá mảnh, xanh mướt, nhìn rất mát. Nhưng dương xỉ **ưa ẩm**, không hợp phòng máy lạnh khô hanh. Chỉ chọn nếu bạn tưới được hằng ngày hoặc đặt cây ở góc không có gió máy lạnh. Bù lại cây an toàn với chó mèo."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/%E6%B3%A2%E5%A3%AB%E9%A0%93%E8%85%8E%E8%95%A8.jpg/960px-%E6%B3%A2%E5%A3%AB%E9%A0%93%E8%85%8E%E8%95%A8.jpg", "caption": "Dương xỉ lá kiếm (Nephrolepis) — lá rủ dài, cần đất luôn ẩm."}, {"type": "h2", "text": "So sánh nhanh 8 cây để bàn"}, {"type": "table", "rows": [["Cây", "Ánh sáng", "Tưới", "Hợp ai"], ["Lưỡi hổ", "Đèn văn phòng được", "7–10 ngày/lần", "Người hay đi vắng"], ["Ngọc ngân", "Tán xạ, chịu bóng", "2–3 lần/tuần", "Muốn lá sáng màu"], ["Phú quý", "Tán xạ, chịu bóng", "2–3 lần/tuần", "Bàn làm việc, quầy thu ngân"], ["Vạn lộc", "Tán xạ, chịu bóng", "2–3 lần/tuần", "Quà tặng, bàn sếp"], ["Lan chi", "Tán xạ, nắng nhẹ", "2–3 lần/tuần", "Nhà có thú cưng"], ["Ngọc bích", "Nắng sáng 4–6 giờ", "1 lần/tuần", "Bàn sát cửa sổ"], ["Môn melo", "Sáng ổn định", "1–2 lần/tuần", "Người thích cây lá lạ"], ["Dương xỉ mini", "Tán xạ, bóng râm", "Mỗi ngày", "Phòng ẩm, không máy lạnh"]]}, {"type": "h2", "text": "Mẹo để cây để bàn sống lâu"}, {"type": "list", "items": ["**Chậu phải có lỗ thoát nước.** Chậu sứ trang trí không lỗ thì để nguyên chậu nhựa trồng bên trong, đổ nước thừa sau khi tưới.", "**Tưới vào đầu tuần.** Tưới thứ Hai thì cây có cả tuần để dùng nước, không bị ướt suốt cuối tuần không ai mở cửa.", "**Mang cây ra chỗ sáng 1 ngày mỗi tuần** nếu bàn rất tối — cạnh cửa sổ, tránh nắng gắt buổi trưa.", "**Lau bụi trên lá** bằng khăn ẩm 2 tuần một lần. Lá phủ bụi văn phòng quang hợp kém hơn hẳn.", "**Không bón phân cho cây vừa mua** trong tháng đầu. Cây cần thời gian quen chỗ mới; bón khi đang yếu dễ cháy rễ."], "ordered": true}, {"type": "note", "title": "Lưu ý nhà có trẻ nhỏ, thú cưng", "text": "Ngọc ngân, phú quý, vạn lộc, môn melo có nhựa chứa tinh thể canxi oxalat gây ngứa miệng nếu nhai phải; lưỡi hổ và ngọc bích độc nhẹ với chó mèo. Nếu nhà có bé hoặc mèo hay gặm lá, ưu tiên lan chi, dương xỉ hoặc nhóm đuôi công."}, {"type": "products", "title": "Cây để bàn có sẵn tại vườn", "slugs": ["luoi-ho", "ngoc-ngan", "phu-quy", "van-loc", "lan-chi", "ngoc-bich"]}, {"type": "p", "text": "Chưa chắc bàn mình hợp cây nào? Dùng [công cụ Tư vấn chọn cây](/tu-van-chon-cay) để trả lời vài câu hỏi về chỗ đặt, hoặc nhắn shop ảnh góc bàn để được gợi ý cụ thể."}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/FY87BH4RPX.jpg', 7, '[]'::jsonb, '["cây để bàn", "văn phòng", "dễ chăm", "máy lạnh"]'::jsonb, '8 cây để bàn làm việc dễ chăm, chịu máy lạnh: lưỡi hổ, ngọc ngân, phú quý, vạn lộc, lan chi, ngọc bích… cách chọn, đặt và tưới để cây xanh lâu.'),
('cay-van-phong-chiu-bong-it-tuoi', 'Cây văn phòng chịu bóng, ít tưới: chọn theo từng vị trí trong công ty', 'Sảnh, góc phòng họp, hành lang hay cạnh bàn sếp — mỗi chỗ trong văn phòng cần một kiểu cây khác nhau. Bài này chia theo vị trí, chọn cây chịu bóng, ít tưới và chỉ cách sắp lịch chăm cho cả công ty.', '[{"type": "p", "text": "Văn phòng là môi trường khá \"khắc nghiệt\" với cây: ánh sáng chủ yếu là đèn, máy lạnh chạy liên tục, cuối tuần và dịp lễ không có ai, người tưới mỗi tuần một khác. Vì vậy cây văn phòng cần ba điều: **chịu bóng, chịu khô, ít rụng lá**."}, {"type": "p", "text": "Thay vì liệt kê thật nhiều cây, bài này đi theo từng vị trí thường có trong một văn phòng và chọn cây hợp với chỗ đó."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/T9AY19HFC0.jpg", "caption": "Văn phòng mở có cây xanh xen giữa các dãy bàn — cây lớn đặt ở mép lối đi, không chắn tầm nhìn."}, {"type": "h2", "text": "Hiểu đúng về \"cây chịu bóng\""}, {"type": "p", "text": "Không có cây nào sống mãi trong bóng tối. \"Chịu bóng\" nghĩa là cây vẫn khỏe với **ánh sáng tán xạ** — ánh sáng hắt từ cửa sổ có rèm, từ giếng trời, hoặc đèn văn phòng bật 8–10 giờ mỗi ngày. Một cách thử đơn giản: đứng ở chỗ định đặt cây, nếu đọc sách thoải mái không cần bật thêm đèn thì cây chịu bóng sống tốt."}, {"type": "p", "text": "Những chỗ hoàn toàn không có cửa sổ, đèn tắt sau giờ làm (kho, phòng họp kín ít dùng) thì nên chọn cây cực bền như lưỡi hổ, và **luân phiên đưa cây ra chỗ sáng** 1–2 tuần mỗi tháng."}, {"type": "h2", "text": "Sảnh và quầy lễ tân: cây lớn, dáng đẹp"}, {"type": "p", "text": "Sảnh là nơi khách nhìn thấy đầu tiên, nên chọn cây cao 70cm–1m, lá to, bóng. Hai lựa chọn bền:"}, {"type": "list", "items": ["[Trầu bà đế vương xanh](/san-pham/trau-ba-de-vuong-xanh) — lá to, bóng, mọc xòe thành tán. Chịu bóng tốt, tưới 2–3 lần mỗi tuần. Loại **3 thân** cho tán dày, đặt một chậu lớn là đủ đầy góc.", "[Vạn niên thanh](/san-pham/van-nien-thanh) — lá loang trắng xanh, dáng đứng, cao 50–60cm. Tên gọi mang ý \"xanh tươi muôn năm\" nên hay được đặt ở sảnh, cạnh quầy."], "ordered": false}, {"type": "p", "text": "Đặt cây sảnh cách cửa ra vào ít nhất 1–2m: gió nóng ngoài trời và gió lạnh trong nhà luân phiên thổi qua cửa làm lá cháy mép."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09417.jpg/960px-Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09417.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Lá trầu bà (Philodendron) to, bóng — non mới ra thường có màu đồng đỏ rồi xanh dần."}, {"type": "h2", "text": "Góc phòng họp, phòng giám đốc"}, {"type": "p", "text": "Đây là chỗ cần cây trông chỉn chu, ít rơi lá xuống sàn:"}, {"type": "list", "items": ["[Bạch mã](/san-pham/bach-ma-hoang-tu) — thân trắng, lá xanh có đốm, mang ý nghĩa thành đạt, thăng tiến; hợp phòng giám đốc, quà thăng chức. Cao 50–70cm.", "[Dạ lan thanh](/san-pham/da-lan-thanh) — lá xanh tốt quanh năm, cao 40cm đến 1m, có cỡ lớn cho góc phòng họp.", "[Ngân hậu](/san-pham/ngan-hau) — lá ánh bạc, sang, chịu bóng tốt; đặt trên kệ hoặc bàn phụ."], "ordered": false}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Dieffenbachia_seguine_photography.jpg/960px-Dieffenbachia_seguine_photography.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Vạn niên thanh (Dieffenbachia) lá loang trắng cao đặt trong hành lang — chịu bóng, ít phải chăm."}, {"type": "h2", "text": "Hành lang, lối đi, góc thiếu sáng"}, {"type": "p", "text": "Hành lang thường hẹp và tối. Chọn cây **dáng đứng, không xòe ra lối đi**:"}, {"type": "list", "items": ["[Lưỡi hổ](/san-pham/luoi-ho) cỡ 50–70cm hoặc chậu C10 — gần như không cần chăm, tưới 7–10 ngày một lần. Đây là cây cứu cánh cho góc tối nhất văn phòng.", "[Vạn niên thanh](/san-pham/van-nien-thanh) — chịu bóng, dáng đứng."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Snake_plant_Sansevieria_growing_in_a_pot_portrait.jpg/960px-Snake_plant_Sansevieria_growing_in_a_pot_portrait.jpg", "caption": "Lưỡi hổ trồng chậu — lá đứng thẳng, gọn, hợp lối đi hẹp."}, {"type": "h2", "text": "Bàn làm việc của nhân viên"}, {"type": "p", "text": "Bàn làm việc nên dùng cây nhỏ dưới 40cm: lưỡi hổ mini, ngọc ngân, phú quý, vạn lộc, lan chi. Chi tiết từng cây có trong bài [8 cây để bàn làm việc dễ chăm](/goc-cham-cay/cay-de-ban-lam-viec-de-cham)."}, {"type": "h2", "text": "Góc có cửa sổ sáng: cây có hoa"}, {"type": "p", "text": "Nếu văn phòng có khu cạnh cửa kính (khu pantry, góc đọc sách), có thể đặt [lan ý](/san-pham/lan-y). Lan ý ra hoa trắng nhiều đợt, chịu được đèn văn phòng, và báo hiệu rất rõ khi khát nước: lá rũ xuống, tưới lại vài giờ là tươi lên. Đây là cây \"nhắc lịch tưới\" rất tiện cho văn phòng."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/2093Peace_Lily_in_the_Philippines_14.jpg/960px-2093Peace_Lily_in_the_Philippines_14.jpg", "caption": "Lan ý (Spathiphyllum) — hoa trắng nở nhiều đợt, lá rũ là dấu hiệu cần tưới."}, {"type": "h2", "text": "Bảng chọn nhanh theo vị trí"}, {"type": "table", "rows": [["Vị trí", "Cây gợi ý", "Cỡ nên chọn", "Tưới"], ["Sảnh, lễ tân", "Trầu bà đế vương xanh, vạn niên thanh", "50cm–1m", "2–3 lần/tuần"], ["Phòng giám đốc", "Bạch mã, ngân hậu", "30–70cm", "2–3 lần/tuần"], ["Phòng họp", "Dạ lan thanh, trầu bà đế vương", "40cm–1m", "2–3 lần/tuần"], ["Hành lang tối", "Lưỡi hổ, vạn niên thanh", "50–70cm", "7–10 ngày (lưỡi hổ)"], ["Góc cửa sổ", "Lan ý, ngân hậu", "30–60cm", "2–3 lần/tuần"]]}, {"type": "h2", "text": "Lập lịch chăm cây cho cả văn phòng"}, {"type": "p", "text": "Nhiều công ty mua cây đẹp nhưng cây chết vì \"ai cũng nghĩ người khác tưới rồi\". Một vài cách đơn giản:"}, {"type": "list", "items": ["**Giao một người phụ trách**, kèm danh sách cây và ngày tưới dán ở pantry.", "**Gom cây theo nhu cầu nước**: nhóm tưới 2–3 lần/tuần (trầu bà, bạch mã, ngân hậu, lan ý) và nhóm tưới 7–10 ngày (lưỡi hổ). Không tưới đồng loạt cho mọi cây.", "**Trước kỳ nghỉ dài** (Tết, lễ 30/4): tưới đẫm trước khi nghỉ, kéo cây khỏi gió máy lạnh, đặt chậu lên khay có lớp sỏi ngâm nước để giữ ẩm.", "**Kiểm tra mặt dưới lá 2 tuần một lần**: văn phòng khô dễ có [nhện đỏ](/benh-cay/nhen-do) và [rệp sáp](/benh-cay/rep-sap). Phát hiện sớm thì chỉ cần lau lá bằng khăn ẩm."], "ordered": true}, {"type": "note", "title": "Không tưới theo lịch cứng", "text": "Lịch tưới chỉ là mốc. Trước khi tưới, cắm ngón tay xuống đất 2–3cm: còn ẩm thì để hôm sau. Đất văn phòng máy lạnh khô chậm hơn ngoài trời, tưới theo lịch cứng dễ làm thối rễ."}, {"type": "products", "title": "Cây văn phòng chịu bóng", "slugs": ["luoi-ho", "trau-ba-de-vuong-xanh", "bach-ma-hoang-tu", "van-nien-thanh", "da-lan-thanh", "ngan-hau"]}, {"type": "p", "text": "Văn phòng cần số lượng nhiều (từ vài chục chậu) hoặc cần cây lớn cho sảnh tòa nhà, bạn có thể [gửi danh sách để nhận báo giá sỉ](/bao-gia-si) — shop gọi lại tư vấn chọn cây theo mặt bằng."}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/T9AY19HFC0.jpg', 5, '[]'::jsonb, '["cây văn phòng", "chịu bóng", "ít tưới", "trang trí công ty"]'::jsonb, 'Chọn cây văn phòng chịu bóng, ít tưới cho sảnh, phòng họp, hành lang, bàn làm việc: lưỡi hổ, trầu bà đế vương, bạch mã, vạn niên thanh, lan ý.'),
('phan-biet-cac-loai-trau-ba-de-vuong', 'Phân biệt trầu bà đế vương xanh, đỏ, vàng, nâu: chọn màu nào cho nhà bạn', 'Trầu bà đế vương là cây lá to được chuộng nhất ở sảnh, phòng khách và văn phòng. Nhà vườn gọi theo màu lá: xanh, đỏ, vàng, nâu, tím. Bài này giúp bạn nhận ra từng loại, biết loại nào hợp chỗ nào và chăm sao cho lá giữ màu.', '[{"type": "p", "text": "\"Trầu bà đế vương\" là tên nhà vườn Việt Nam dùng cho một nhóm giống trầu bà lai (chi Philodendron) có lá to, dày, bóng, mọc thành bụi từ gốc chứ không leo dài như trầu bà thường. Các giống phổ biến trên thị trường quốc tế có tên như Imperial Green, Imperial Red. Ở vườn, người bán thường gọi tắt theo **màu lá**: đế xanh, đế đỏ, đế vàng, đế nâu…"}, {"type": "p", "text": "Vì là cây lai, cùng một tên nhưng mỗi vườn có thể hơi khác nhau về sắc độ. Cách nhận biết chắc nhất vẫn là nhìn **lá non** và **cuống lá**."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09417.jpg/960px-Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09417.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Lá non của trầu bà thường ra màu đồng đỏ rồi xanh dần khi lá trưởng thành."}, {"type": "h2", "text": "Điểm chung của cả nhóm đế vương"}, {"type": "list", "items": ["Lá to bản, dày, bóng, mọc xòe thành tán từ gốc; cây cao 50cm–1m khi trồng chậu.", "**Chịu bóng tốt**: sống khỏe với ánh sáng tán xạ, đèn văn phòng. Nắng gắt chiếu thẳng làm cháy lá.", "Tưới khi mặt đất khô 2–3cm, khoảng 2–3 lần mỗi tuần, không để đọng nước dưới đĩa.", "Có nhựa chứa tinh thể canxi oxalat — gây ngứa nếu nhai phải, cần để xa trẻ nhỏ và thú cưng."], "ordered": false}, {"type": "p", "text": "Khác biệt chủ yếu nằm ở màu lá, và màu lá ảnh hưởng tới **nhu cầu ánh sáng**: lá càng nhiều sắc đỏ, vàng, càng cần sáng hơn để giữ màu."}, {"type": "h2", "text": "Đế vương xanh — bền nhất, dễ phối nhất"}, {"type": "p", "text": "[Trầu bà đế vương xanh](/san-pham/trau-ba-de-vuong-xanh) có lá xanh lục bóng, lá non xanh nhạt. Đây là loại chịu bóng tốt nhất trong nhóm, hợp góc thiếu sáng, sảnh, văn phòng. Màu xanh trung tính nên đặt cạnh nội thất nào cũng hợp."}, {"type": "p", "text": "Theo quan niệm dân gian, đế vương xanh tượng trưng cho thịnh vượng, thăng tiến, hợp mệnh Mộc và Hỏa. Loại **3 thân** cho tán dày gấp mấy lần loại một thân, hợp chậu lớn đặt sàn."}, {"type": "h2", "text": "Đế vương đỏ — điểm nhấn cho phòng khách"}, {"type": "p", "text": "[Trầu bà đế vương đỏ](/san-pham/trau-ba-de-vuong-do) có lá non đỏ rượu vang, lá già chuyển đỏ sẫm pha xanh, cuống lá đỏ. Đặt ở phòng khách, cạnh sofa sáng màu rất nổi bật. Sắc đỏ được xem là may mắn, hợp mệnh Hỏa, Thổ, nên đế đỏ hay được chọn làm quà khai trương."}, {"type": "p", "text": "Muốn lá đỏ đậm, đặt cây gần cửa sổ có rèm. Để quá tối lâu ngày, lá mới ra sẽ xanh dần và kém đỏ."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09419.jpg/960px-Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09419.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Cuống và lá non màu đỏ là đặc điểm dễ nhận của các giống trầu bà lá đỏ."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/e/e9/Philodendron_davidsonii2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "caption": "Chi Philodendron có hàng trăm loài và giống lai — nhóm đế vương là các giống mọc bụi, lá to, không leo."}, {"type": "h2", "text": "Đế vương vàng — sáng cả góc phòng"}, {"type": "p", "text": "[Trầu bà đế vương vàng](/san-pham/trau-ba-de-vuong-vang) có lá non vàng chanh, lá già vàng xanh. Đây là loại làm góc phòng \"sáng\" lên rõ nhất, hợp phòng sơn tối màu hoặc nội thất gỗ đậm. Lá vàng cần sáng nhiều hơn đế xanh — để chỗ quá tối lá sẽ xanh lại."}, {"type": "h2", "text": "Đế vương nâu — sang và trầm"}, {"type": "p", "text": "[Trầu bà đế vương nâu](/san-pham/trau-ba-de-vuong-nau) có lá màu nâu đồng đến nâu sẫm, nhìn trầm và sang, hợp không gian tối giản, văn phòng giám đốc. Có cỡ chậu C9 và cỡ 3 thân."}, {"type": "h2", "text": "Các giống khác trong nhóm: đế tím Pháp, đế kim cương"}, {"type": "p", "text": "Ngoài 4 màu chính, vườn còn có [Đế tím Pháp](/san-pham/de-tim-phap) với lá ánh tím và [Đế vương kim cương 3 thân](/san-pham/de-kim-cuong). Đây là tên thương mại nhà vườn đặt, cách chăm giống các loại đế vương khác: ánh sáng tán xạ, tưới khi đất mặt khô."}, {"type": "h2", "text": "Bảng so sánh"}, {"type": "table", "rows": [["Loại", "Màu lá non", "Nhu cầu ánh sáng", "Hợp chỗ nào"], ["Đế xanh", "Xanh nhạt", "Chịu bóng tốt nhất", "Sảnh, văn phòng, góc tối"], ["Đế đỏ", "Đỏ rượu vang", "Cần sáng vừa", "Phòng khách, quà khai trương"], ["Đế vàng", "Vàng chanh", "Cần sáng vừa đến nhiều", "Phòng sơn tối, nội thất gỗ"], ["Đế nâu", "Nâu đồng", "Cần sáng vừa", "Văn phòng giám đốc, không gian tối giản"]]}, {"type": "h2", "text": "Chăm đế vương để lá to, giữ màu"}, {"type": "list", "items": ["**Xoay chậu 1/4 vòng mỗi tuần** để cây không nghiêng về phía cửa sổ, tán đều.", "**Lau lá bằng khăn ẩm** 2 tuần một lần — lá to dễ đọng bụi, lau xong bóng đẹp ngay.", "**Bón phân tan chậm** 2–3 tháng một lần vào mùa cây ra lá (mùa mưa). Không bón khi cây vừa chuyển chậu.", "**Cắt lá già vàng** sát gốc cuống để cây dồn sức nuôi lá mới.", "**Thay chậu** khi rễ mọc ra lỗ đáy, thường 1–2 năm một lần, chọn chậu lớn hơn 1 cỡ."], "ordered": true}, {"type": "note", "title": "Lá vàng hàng loạt từ dưới lên", "text": "Thường do tưới quá nhiều, đất bí. Kiểm tra đất: nếu ướt nhão, có mùi hôi thì ngưng tưới, xem hướng dẫn xử lý [thối rễ](/benh-cay/thoi-re). Lá vàng lẻ tẻ ở tầng dưới cùng là lá già tự nhiên, không đáng lo."}, {"type": "products", "title": "Trầu bà đế vương tại vườn", "slugs": ["trau-ba-de-vuong-xanh", "trau-ba-de-vuong-do", "trau-ba-de-vuong-vang", "trau-ba-de-vuong-nau", "de-tim-phap", "de-kim-cuong"]}, {"type": "p", "text": "Ảnh minh họa trong bài là ảnh tư liệu cây cùng chi Philodendron. Ảnh từng cây tại vườn xem ở trang sản phẩm; muốn xem cây thật trước khi mua, nhắn shop qua Zalo để được gửi ảnh, video cây đang có."}]'::jsonb, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09417.jpg/960px-Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09417.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 5, '[]'::jsonb, '["trầu bà đế vương", "philodendron", "cây phòng khách", "so sánh"]'::jsonb, 'Phân biệt trầu bà đế vương xanh, đỏ, vàng, nâu, đế tím, đế kim cương: đặc điểm lá, vị trí đặt, ý nghĩa phong thủy và cách chăm giữ màu lá.'),
('phan-biet-cay-duoi-cong-calathea', 'Cây đuôi công (Calathea): phân biệt đuôi công tím, xanh, phụng và cách giữ lá không cháy mép', 'Đuôi công là nhóm cây lá đẹp nhất trong các loại cây trong nhà, nhưng cũng hay bị cháy mép lá nhất. Bài này giúp bạn phân biệt các loại đuôi công phổ biến, chọn đúng chỗ đặt và giữ ẩm để lá luôn tươi.', '[{"type": "p", "text": "\"Đuôi công\" là tên gọi chung cho nhiều loài cây thuộc họ Hoàng tinh (Marantaceae), phần lớn trước đây xếp vào chi Calathea, nay nhiều loài được chuyển sang chi Goeppertia. Điểm chung dễ thấy: lá có hoa văn như lông đuôi chim công, mặt dưới lá thường tím đỏ, và **lá cụp lên vào buổi tối, xòe ra ban ngày**."}, {"type": "p", "text": "Đuôi công đẹp nhưng \"khó tính\" hơn trầu bà hay lưỡi hổ một chút. Hiểu cây cần gì thì chăm không khó."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Goeppertia_makoyana_in_Guangzhou_Baiyun_International_Airport_T2.jpg/960px-Goeppertia_makoyana_in_Guangzhou_Baiyun_International_Airport_T2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Đuôi công Calathea makoyana trồng chậu — hoa văn lá như lông đuôi công."}, {"type": "h2", "text": "Vì sao nên chọn đuôi công?"}, {"type": "list", "items": ["**An toàn với chó mèo**: các loại đuôi công không độc, là lựa chọn tốt cho nhà có thú cưng, trẻ nhỏ.", "**Chịu bóng**: sống tốt với ánh sáng tán xạ nhẹ; nắng trực tiếp ngược lại làm bạc và cháy lá.", "**Kích thước gọn**: cao 30–60cm, hợp bàn, kệ, góc phòng.", "Lá chuyển động theo ngày đêm, nhìn rất \"sống\", trẻ con thường thích."], "ordered": false}, {"type": "h2", "text": "Phân biệt các loại đuôi công phổ biến"}, {"type": "h3", "text": "Đuôi công tím"}, {"type": "p", "text": "[Đuôi công tím](/san-pham/duoi-cong-tim) có mặt dưới lá tím đậm, mặt trên hoa văn xanh. Khi lá cụp lên buổi tối, mặt tím lộ ra rất đẹp. Có cỡ 20–30cm cho bàn và 30–50cm cho kệ."}, {"type": "h3", "text": "Đuôi công xanh"}, {"type": "p", "text": "[Đuôi công xanh](/san-pham/duoi-cong-xanh) có tông xanh là chủ đạo, hoa văn đậm nhạt trên nền lá xanh. Màu dịu, dễ phối, hợp phòng ngủ và bàn làm việc."}, {"type": "h3", "text": "Đuôi công phụng"}, {"type": "p", "text": "[Đuôi công phụng](/san-pham/duoi-phung) (Goeppertia lancifolia, tên tiếng Anh rattlesnake plant) có lá dài, hẹp, mép lượn sóng, đốm xanh đậm xếp hai bên gân như vảy. Dáng lá đứng, thanh, hợp đặt kệ cao hoặc góc hẹp. Đây cũng là loại khá dễ chăm trong nhóm."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Goeppertia_rufibarba_-_Kew_Gardens%2C_London_-_DSC03565.jpg/960px-Goeppertia_rufibarba_-_Kew_Gardens%2C_London_-_DSC03565.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Một loài Goeppertia lá dài hẹp, hoa văn đốm hai bên gân — dáng lá gần giống đuôi công phụng."}, {"type": "h3", "text": "Công khổng tước"}, {"type": "p", "text": "[Công khổng tước](/san-pham/cong-khong-tuoc) là tên nhà vườn dùng cho một loại đuôi công lá hoa văn nổi, trồng chậu sẵn. Cách chăm giống các loại đuôi công khác."}, {"type": "h3", "text": "Các loài đuôi công khác bạn có thể gặp"}, {"type": "p", "text": "Thị trường còn nhiều loài đuôi công khác như lá sọc hồng (Calathea ornata), lá tròn to sọc bạc (Calathea orbifolia), lá nhung (Calathea warscewiczii). Nhìn chung càng lá to, lá nhung thì càng cần độ ẩm cao."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Goeppertia_elliptica_2.jpg/960px-Goeppertia_elliptica_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Lá sọc mảnh màu hồng trắng của Calathea ornata."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Goeppertia_loeseneri_-_Kew_Gardens%2C_London_-_DSC03584.jpg/960px-Goeppertia_loeseneri_-_Kew_Gardens%2C_London_-_DSC03584.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Calathea orbifolia — lá tròn to, sọc bạc, cần độ ẩm cao."}, {"type": "h2", "text": "Vì sao đuôi công hay cháy mép lá?"}, {"type": "p", "text": "Đây là câu hỏi shop nhận nhiều nhất. Nguyên nhân thường gặp, xếp theo mức độ phổ biến:"}, {"type": "list", "items": ["**Không khí khô**: phòng máy lạnh độ ẩm có thể xuống thấp, mép lá khô giòn, nâu dần vào trong.", "**Đất khô kiệt rồi tưới dồn**: đuôi công thích đất **hơi ẩm đều**, không thích khô hẳn rồi mới tưới như lưỡi hổ.", "**Nước máy nhiều clo**: một số loài đuôi công nhạy với nước máy. Hứng nước để lắng qua đêm rồi mới tưới.", "**Nắng chiếu thẳng**: lá bạc màu, cháy thành mảng (xem [cháy lá do nắng](/benh-cay/chay-la-do-nang)).", "**Bón phân quá liều**: mép lá cháy đều, đất có lớp muối trắng."], "ordered": true}, {"type": "h2", "text": "Cách chăm đuôi công lá luôn tươi"}, {"type": "list", "items": ["**Tưới 2–3 lần mỗi tuần**, giữ đất hơi ẩm, không để nước đọng dưới đĩa.", "**Tăng độ ẩm**: đặt chậu lên khay sỏi có nước (đáy chậu không chạm nước), hoặc gom nhiều chậu cây gần nhau. Phun sương buổi sáng giúp thêm, nhưng tránh phun buổi tối để lá không ướt qua đêm.", "**Đặt xa máy lạnh, quạt**: luồng gió thổi thẳng là nguyên nhân số một gây cháy mép.", "**Bón loãng**: dùng phân tan chậm hoặc phân nước pha loãng một nửa liều, 1–2 tháng một lần mùa mưa.", "**Cắt bỏ lá cháy**: cắt phần cháy theo đường mép lá cho đẹp, hoặc cắt cả lá sát gốc nếu cháy quá nửa."], "ordered": false}, {"type": "table", "rows": [["Tình trạng", "Nguyên nhân thường gặp", "Cách xử lý"], ["Mép lá nâu, giòn", "Không khí khô, gió máy lạnh", "Dời chỗ, khay sỏi nước"], ["Lá cuộn tròn ban ngày", "Thiếu nước", "Tưới đẫm, giữ ẩm đều"], ["Lá vàng, gốc mềm", "Tưới quá nhiều", "Ngưng tưới, kiểm tra rễ"], ["Lá bạc màu, có mảng trắng", "Nắng chiếu thẳng", "Dời vào chỗ ánh sáng tán xạ"], ["Mặt dưới lá có chấm, tơ mịn", "Nhện đỏ", "Lau lá, xem [nhện đỏ](/benh-cay/nhen-do)"]]}, {"type": "note", "title": "Đừng lo khi lá cụp lại buổi tối", "text": "Đó là chuyển động tự nhiên của họ Hoàng tinh (tiếng Anh gọi là \"prayer plant\" — cây cầu nguyện), không phải cây bị héo. Chỉ đáng lo khi lá cuộn lại vào ban ngày."}, {"type": "products", "title": "Đuôi công có sẵn tại vườn", "slugs": ["duoi-cong-tim", "duoi-cong-xanh", "duoi-phung", "cong-khong-tuoc"]}, {"type": "p", "text": "Đuôi công là cây an toàn cho nhà có thú cưng — xem thêm các cây khác trong bài [cây cảnh an toàn cho trẻ nhỏ và chó mèo](/goc-cham-cay/cay-canh-an-toan-tre-nho-thu-cung)."}]'::jsonb, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Goeppertia_makoyana_in_Guangzhou_Baiyun_International_Airport_T2.jpg/960px-Goeppertia_makoyana_in_Guangzhou_Baiyun_International_Airport_T2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 4, '[]'::jsonb, '["đuôi công", "calathea", "cây trong nhà", "an toàn thú cưng"]'::jsonb, 'Phân biệt cây đuôi công tím, đuôi công xanh, đuôi công phụng (Calathea): đặc điểm lá, an toàn thú cưng, cách tưới và giữ ẩm để lá không cháy mép.'),
('mon-quan-am-va-mon-melo', 'Môn quan âm và môn melo: hai cây môn lá đẹp, chọn loại nào và chăm sao để không thối củ', 'Môn quan âm có lá hình mũi tên gân bạc nổi bật, môn melo có lá dày sần như da tê giác. Cả hai đều là cây lá đẹp để bàn, kệ, nhưng chung một điểm yếu: củ dễ thối khi úng nước. Bài này so sánh hai loại và chỉ cách chăm đúng.', '[{"type": "p", "text": "Chi Môn (Alocasia) có hàng chục loài với lá rất ấn tượng: lá to hình tim, hình mũi tên, gân trắng nổi, mặt lá như nhung hay như da. Trong nhà ở Việt Nam, hai loại được chuộng vì cỡ nhỏ gọn, hợp bàn và kệ là **môn quan âm** và **môn melo**."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Alocasia_micholitziana_3.JPG/960px-Alocasia_micholitziana_3.JPG", "caption": "Một loài môn (Alocasia) lá mũi tên gân trắng — kiểu lá quen thuộc của nhóm môn cảnh."}, {"type": "h2", "text": "Môn quan âm — lá mũi tên, gân bạc"}, {"type": "p", "text": "[Môn quan âm](/san-pham/mon-quan-am) là giống lai Alocasia × amazonica, trên thị trường quốc tế hay gọi là \"Polly\" hoặc \"African mask\". Lá xanh đậm gần như đen, hình mũi tên, mép lượn sóng, gân trắng bạc nổi rõ. Cây vươn thẳng, cao 40–60cm khi trưởng thành."}, {"type": "list", "items": ["**Ánh sáng**: tán xạ sáng, gần cửa sổ có rèm. Thiếu sáng lâu, cuống lá vươn dài, lá nhỏ và nhạt màu.", "**Tưới**: khi mặt đất khô 2–3cm, khoảng 2 lần mỗi tuần.", "**Hợp**: bàn làm việc gần cửa sổ, kệ phòng khách, làm quà. Có cỡ 20–30cm và 40–60cm."], "ordered": false}, {"type": "h2", "text": "Môn melo — lá dày sần như da tê giác"}, {"type": "p", "text": "[Môn melo](/san-pham/mon-melo) (Alocasia melo, nguồn gốc đảo Borneo) có lá dày, cứng, mặt lá sần sùi như da, màu xanh lam đậm. Cây lớn chậm, giữ dáng nhỏ gọn rất lâu, cao 30–60cm."}, {"type": "list", "items": ["**Ánh sáng**: tán xạ sáng, ổn định; tránh nắng chiếu thẳng làm cháy lá.", "**Tưới**: lá dày nên chịu khô hơn các loại môn khác — 1–2 lần mỗi tuần khi đất mặt khô.", "**Hợp**: người thích sưu tầm cây lá lạ, bàn làm việc, kệ."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Alocasia_sinuata_%28Philippines%29_0010.jpg/960px-Alocasia_sinuata_%28Philippines%29_0010.jpg", "caption": "Môn trồng chậu nhỏ — lá dày, đặt nơi sáng ổn định."}, {"type": "h2", "text": "So sánh nhanh"}, {"type": "table", "rows": [["Tiêu chí", "Môn quan âm", "Môn melo"], ["Hình lá", "Mũi tên, mép lượn sóng", "Tim tròn, dày, sần"], ["Màu lá", "Xanh đen, gân bạc nổi", "Xanh lam đậm"], ["Tốc độ lớn", "Trung bình", "Chậm"], ["Chịu khô", "Trung bình", "Khá hơn"], ["Điểm yếu", "Dễ thối củ khi úng, dễ có nhện đỏ khi khô", "Dễ thối củ khi úng"], ["Hợp ai", "Muốn cây nổi bật, làm quà", "Người thích cây lạ, ít thay đổi"]]}, {"type": "h2", "text": "Điều quan trọng nhất: không để úng"}, {"type": "p", "text": "Cả hai loại môn đều mọc từ **củ** (thân rễ). Củ ngâm nước lâu sẽ thối mềm, cây sụp nhanh mà không kịp báo trước. Một số nguyên tắc:"}, {"type": "list", "items": ["**Chậu phải thoát nước tốt**, đất tơi trộn nhiều xơ dừa, đá perlite hoặc vỏ thông. Không dùng đất thịt nặng.", "**Đổ nước thừa** dưới đĩa 15–20 phút sau khi tưới.", "**Mùa mưa giảm tưới**: trời âm u, đất khô chậm, nhiều khi cả tuần mới cần tưới một lần.", "**Chậu vừa cỡ rễ**: chậu quá to so với cây giữ nước lâu, dễ úng hơn chậu vừa."], "ordered": true}, {"type": "note", "title": "Cây tự rụng hết lá — chưa chắc đã chết", "text": "Môn có thể vào giai đoạn nghỉ khi thời tiết thay đổi, vừa chuyển chỗ hoặc thiếu sáng kéo dài: lá vàng rụng dần, chỉ còn củ. Đừng vứt đi. Bới nhẹ xem củ: nếu củ còn chắc, không mềm, không hôi thì giữ đất hơi khô, để chỗ sáng ấm, vài tuần cây sẽ ra lá mới."}, {"type": "h2", "text": "Xử lý các vấn đề thường gặp"}, {"type": "list", "items": ["**Lá vàng từ lá già nhất**: bình thường — môn thường giữ 3–5 lá, ra lá mới thì lá già nhất vàng đi. Cắt sát gốc cuống.", "**Nhiều lá vàng cùng lúc, gốc mềm**: úng nước, nghi [thối rễ](/benh-cay/thoi-re) hoặc [thối nhũn](/benh-cay/thoi-nhun). Ngưng tưới, rút cây kiểm tra, cắt phần thối, chấm vôi hoặc thuốc trị nấm, trồng lại vào đất mới khô ráo.", "**Mặt dưới lá có chấm li ti, tơ mịn, lá mờ màu**: [nhện đỏ](/benh-cay/nhen-do), hay gặp ở phòng máy lạnh khô. Lau mặt dưới lá bằng khăn ẩm, tăng độ ẩm quanh cây.", "**Lá có đốm nâu viền vàng**: [đốm lá do nấm](/benh-cay/dom-la-nam), thường do tưới lên lá buổi tối. Tưới vào gốc, cắt bỏ lá bệnh."], "ordered": false}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/4M8QRWO0YA.jpg", "caption": "Đất trồng môn nên tơi, thoát nước; chậu luôn có lỗ đáy."}, {"type": "h2", "text": "Lưu ý an toàn"}, {"type": "p", "text": "Cây họ Ráy (Araceae) như môn có nhựa chứa tinh thể canxi oxalat. Nhai phải lá gây ngứa, rát miệng, chảy nước bọt — với chó mèo có thể nôn. Đặt cây trên kệ cao nếu nhà có trẻ nhỏ, thú cưng; rửa tay sau khi cắt tỉa."}, {"type": "products", "title": "Môn cảnh tại vườn", "slugs": ["mon-quan-am", "mon-melo"]}, {"type": "p", "text": "Thích cây lá đẹp nhưng muốn dễ chăm hơn môn? Xem nhóm [trầu bà đế vương](/goc-cham-cay/phan-biet-cac-loai-trau-ba-de-vuong) — lá cũng to, đẹp mà ít bị thối củ hơn nhiều."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Alocasia_micholitziana_3.JPG/960px-Alocasia_micholitziana_3.JPG', 4, '[]'::jsonb, '["môn quan âm", "môn melo", "alocasia", "cây lá đẹp"]'::jsonb, 'So sánh môn quan âm (Alocasia Polly) và môn melo (Alocasia melo): đặc điểm lá, ánh sáng, cách tưới tránh thối củ, xử lý lá vàng và mùa cây nghỉ.'),
('phan-biet-phu-quy-van-loc-ngoc-ngan-ngan-hau', 'Phú quý, vạn lộc, ngọc ngân, ngân hậu, bạch mã: phân biệt nhóm cây Aglaonema', 'Năm cây hay bị nhầm với nhau nhất ở tiệm cây là phú quý, vạn lộc, ngọc ngân, ngân hậu và bạch mã — vì chúng cùng một chi Aglaonema. Bài này chỉ cách nhìn lá để nhận ra từng cây, ý nghĩa tên gọi và cách chăm chung cho cả nhóm.', '[{"type": "p", "text": "Aglaonema là một chi cây thuộc họ Ráy, quê ở vùng rừng nhiệt đới châu Á — kể cả Việt Nam. Từ vài loài hoang dại, người ta lai tạo ra hàng trăm giống có lá đỏ, hồng, bạc, loang trắng. Ở Việt Nam, mỗi giống được đặt một tên mang ý nghĩa may mắn: **phú quý, vạn lộc, ngọc ngân, ngân hậu, bạch mã**…"}, {"type": "p", "text": "Vì cùng chi, cả nhóm có cách chăm gần như giống hệt nhau. Khác biệt chính là **màu lá** — và màu lá quyết định cây hợp chỗ nào."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Aglaonema_commutatum_-_Saigon_Zoo_and_Botanical_Gardens_-_Ho_Chi_Minh_City%2C_Vietnam_-_DSC01286.JPG/960px-Aglaonema_commutatum_-_Saigon_Zoo_and_Botanical_Gardens_-_Ho_Chi_Minh_City%2C_Vietnam_-_DSC01286.JPG", "caption": "Aglaonema commutatum trồng chậu tại Thảo Cầm Viên Sài Gòn — chi cây có nguồn gốc ngay tại vùng nhiệt đới châu Á."}, {"type": "h2", "text": "Phú quý — lá xanh viền, gân đỏ hồng"}, {"type": "p", "text": "[Phú quý](/san-pham/phu-quy) là giống lai lá đỏ: phiến lá xanh hoặc hồng, viền và gân đỏ hồng nổi rõ. Tên gọi cùng sắc đỏ gắn với \"phú quý, giàu sang\", nên đây là cây quà khai trương, tân gia phổ biến nhất. Theo dân gian, phú quý hợp mệnh Hỏa, Thổ."}, {"type": "p", "text": "Có nhiều cỡ: 20–30cm cho bàn, 30–50cm cho kệ, góc phòng."}, {"type": "h2", "text": "Vạn lộc — lá hồng đỏ nhiều hơn xanh"}, {"type": "p", "text": "[Vạn lộc](/san-pham/van-loc) (còn gọi thiên phú) thường có lá ửng hồng đỏ rộng hơn phú quý, phần xanh chỉ còn ở mép hoặc thành đốm. Tên gọi mang ý \"vạn sự may mắn, tài lộc dồi dào\", hợp mệnh Hỏa, Thổ. Lá tròn bầu, dày, cây mọc thành bụi đều."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Aglaonema_%27Pink_Star%27.webp/960px-Aglaonema_%27Pink_Star%27.webp", "caption": "Giống Aglaonema lá hồng — lá ửng hồng gần hết phiến như nhóm vạn lộc."}, {"type": "h2", "text": "Ngọc ngân — lá đốm trắng như ngọc"}, {"type": "p", "text": "[Ngọc ngân](/san-pham/ngoc-ngan) có lá xanh loang đốm trắng dày đặc, nhìn như rắc bột trắng lên lá; cuống lá trắng xanh. Tượng trưng cho tình yêu bền chặt, bình an — hay được tặng cho các cặp đôi. Hợp mệnh Kim, Thủy. Cỡ 25–30cm rất hợp bàn làm việc."}, {"type": "h2", "text": "Ngân hậu — lá ánh bạc"}, {"type": "p", "text": "[Ngân hậu](/san-pham/ngan-hau) thuộc nhóm giống \"Silver Queen\": lá dài, phần lớn phiến lá phủ màu xám bạc, chỉ còn vệt xanh dọc gân. Sắc bạc trông sang, chịu bóng tốt, hợp phòng khách, văn phòng. Hợp mệnh Kim, Thủy."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Aglaonema_marantifolium_-_United_States_Botanic_Garden_-_DSC09589.JPG/960px-Aglaonema_marantifolium_-_United_States_Botanic_Garden_-_DSC09589.JPG", "caption": "Một loài Aglaonema lá loang bạc — kiểu lá của nhóm ngân hậu."}, {"type": "h2", "text": "Bạch mã — thân trắng, lá dài"}, {"type": "p", "text": "[Bạch mã](/san-pham/bach-ma-hoang-tu) (bạch mã hoàng tử, Aglaonema pseudobracteatum) dễ nhận nhất ở **thân và cuống lá màu trắng ngà**, lá dài thuôn có vệt xanh vàng. Cây cao hơn các giống khác, 50–70cm, dáng thanh. Mang ý nghĩa thành đạt, thăng tiến — quà thăng chức, phòng giám đốc. Hợp mệnh Kim, Thủy."}, {"type": "h2", "text": "Bảng nhận biết nhanh"}, {"type": "table", "rows": [["Cây", "Dấu hiệu dễ nhận", "Ý nghĩa", "Hợp mệnh"], ["Phú quý", "Lá xanh viền, gân đỏ hồng", "Giàu sang, may mắn", "Hỏa, Thổ"], ["Vạn lộc", "Lá ửng hồng đỏ gần hết phiến", "Vạn sự may mắn, tài lộc", "Hỏa, Thổ"], ["Ngọc ngân", "Lá xanh rắc đốm trắng", "Tình yêu bền chặt, bình an", "Kim, Thủy"], ["Ngân hậu", "Lá phủ xám bạc", "Sang trọng, bình an", "Kim, Thủy"], ["Bạch mã", "Thân, cuống trắng ngà; lá dài", "Thành đạt, thăng tiến", "Kim, Thủy"]]}, {"type": "p", "text": "Ý nghĩa và mệnh hợp là theo quan niệm dân gian về màu sắc, để bạn tham khảo khi chọn quà."}, {"type": "h2", "text": "Cách chăm chung cho cả nhóm Aglaonema"}, {"type": "p", "text": "Tin vui là cả 5 cây chăm giống nhau và đều thuộc nhóm **dễ chăm**:"}, {"type": "list", "items": ["**Ánh sáng tán xạ, chịu bóng tốt.** Giống lá đỏ, hồng cần sáng hơn một chút để giữ màu; giống lá xanh bạc chịu tối tốt hơn.", "**Tưới khi mặt đất khô 2–3cm**, khoảng 2–3 lần mỗi tuần. Không để nước đọng dưới đĩa.", "**Nhiệt độ ấm**: cây quê nhiệt đới nên rất hợp khí hậu miền Nam; tránh đặt sát cửa gió máy lạnh.", "**Bón phân tan chậm** 2–3 tháng một lần vào mùa mưa.", "**Tách bụi** khi cây quá dày: rút cây ra, tách từng cụm có rễ, trồng chậu riêng — cách nhân giống đơn giản nhất."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/9714Philippines_Elephant_ear_Aglaonema_16.jpg/960px-9714Philippines_Elephant_ear_Aglaonema_16.jpg", "caption": "Aglaonema trồng chậu nhỏ — cả nhóm hợp đặt bàn, kệ, chịu bóng tốt."}, {"type": "note", "title": "Lá mới ra kém đỏ, xanh dần", "text": "Cây thiếu sáng. Dời cây gần cửa sổ có rèm, lá mới sẽ đậm màu trở lại. Lá cũ đã xanh thì không đỏ lại được."}, {"type": "note", "title": "Lưu ý an toàn", "text": "Nhóm Aglaonema có nhựa chứa tinh thể canxi oxalat gây ngứa, độc nếu nhai phải. Đặt xa tầm với trẻ nhỏ và chó mèo."}, {"type": "products", "title": "Nhóm Aglaonema tại vườn", "slugs": ["phu-quy", "van-loc", "ngoc-ngan", "ngan-hau", "bach-ma-hoang-tu"]}, {"type": "p", "text": "Chọn cây làm quà theo dịp? Xem thêm [cây cảnh làm quà khai trương, tân gia, sinh nhật](/goc-cham-cay/chon-cay-qua-tang-khai-truong-tan-gia)."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Aglaonema_commutatum_-_Saigon_Zoo_and_Botanical_Gardens_-_Ho_Chi_Minh_City%2C_Vietnam_-_DSC01286.JPG/960px-Aglaonema_commutatum_-_Saigon_Zoo_and_Botanical_Gardens_-_Ho_Chi_Minh_City%2C_Vietnam_-_DSC01286.JPG', 4, '[]'::jsonb, '["phú quý", "vạn lộc", "ngọc ngân", "aglaonema", "cây phong thủy"]'::jsonb, 'Phân biệt cây phú quý, vạn lộc, ngọc ngân, ngân hậu, bạch mã (Aglaonema): cách nhận biết qua màu lá, ý nghĩa phong thủy, hợp mệnh và cách chăm.'),
('chon-cay-cong-trinh-duong-pho-san-truong', 'Chọn cây công trình cho đường phố, sân trường, khu dân cư: bằng lăng, phượng vĩ, giáng hương hay dầu rái?', 'Cây bóng mát trồng một lần sống mấy chục năm, chọn sai thì nứt vỉa hè, gãy cành mùa mưa bão hay rụng lá bít cống. Bài này so sánh 7 loại cây công trình phổ biến ở miền Nam và chỉ cách chọn theo từng loại công trình.', '[{"type": "p", "text": "Với chủ đầu tư, đơn vị cảnh quan hay ban quản lý khu dân cư, chọn cây bóng mát khác hẳn chọn cây chậu: cây sẽ đứng đó **20–50 năm**, lớn lên cao hơn nhà 2–3 tầng, rễ lan dưới vỉa hè, cành vươn qua đường dây điện. Một cây chọn sai có thể tốn kém hơn nhiều so với tiền mua cây ban đầu."}, {"type": "p", "text": "Bài này so sánh các loại cây công trình phổ biến ở miền Nam theo những tiêu chí thực tế: tán, rễ, độ bền gió, mùa hoa và lá rụng."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Delonix_regia_Sunbury_Street_Geebung_P1130442.jpg/960px-Delonix_regia_Sunbury_Street_Geebung_P1130442.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Hàng phượng vĩ trồng dọc đường khu dân cư — tán xòe rộng, hoa đỏ rực đầu mùa mưa."}, {"type": "h2", "text": "5 câu hỏi trước khi chọn cây công trình"}, {"type": "list", "items": ["**Khoảng trống phía trên bao nhiêu?** Có đường dây điện, mái hiên, biển hiệu không? Cây tán rộng cần khoảng trống lớn.", "**Khoảng đất cho rễ bao nhiêu?** Dải phân cách hẹp, hố trồng trên vỉa hè nhỏ thì tránh cây rễ ngang mạnh.", "**Ai chăm sau khi trồng?** Cây cần tỉa tán định kỳ hay để tự nhiên?", "**Lá, hoa, quả rụng có gây phiền không?** Bãi xe, hồ bơi, mái tôn, cống thoát nước…", "**Muốn hoa hay muốn bóng mát quanh năm?** Cây hoa đẹp thường có mùa rụng lá."], "ordered": true}, {"type": "h2", "text": "Bằng lăng — hoa tím, tán gọn"}, {"type": "p", "text": "[Bằng lăng](/san-pham/bang-lang) (Lagerstroemia speciosa) cho hoa tím thành chùm lớn vào khoảng đầu mùa hè. Tán trung bình, ít xòe rộng như phượng, rễ ăn sâu nên ít làm nứt vỉa hè. Rất hợp đường nội bộ, sân trường, công viên. Mùa khô cây rụng lá một thời gian ngắn."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/0049Lagerstroemia_speciosa_40.jpg/960px-0049Lagerstroemia_speciosa_40.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Hoa bằng lăng tím mọc thành chùm lớn ở đầu cành."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/0049Lagerstroemia_speciosa_37.jpg/960px-0049Lagerstroemia_speciosa_37.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Bằng lăng trồng ven đường — tán gọn, hợp dải đất hẹp."}, {"type": "h2", "text": "Phượng vĩ — tán dù rộng, hoa đỏ mùa hè"}, {"type": "p", "text": "[Phượng vĩ](/san-pham/phuong-vi) (Delonix regia) có tán xòe rộng hình dù, bóng mát lớn, hoa đỏ cam rực rỡ — gắn liền với sân trường. Nhược điểm: gỗ giòn, cành dễ gãy khi gió mạnh nếu không tỉa; rễ ngang lan rộng gần mặt đất. Hợp sân trường rộng, công viên, khuôn viên có nhiều đất trống; nên tránh hố trồng nhỏ sát nhà."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Delonix_regia_Sunbury_Street_Geebung_P1130416.jpg/960px-Delonix_regia_Sunbury_Street_Geebung_P1130416.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Một cây phượng vĩ trưởng thành — tán rộng, bóng mát lớn, cần khoảng trống xung quanh."}, {"type": "h2", "text": "Kèn hồng — hoa hồng phấn, tán thoáng"}, {"type": "p", "text": "[Kèn hồng](/san-pham/ken-hong) (Tabebuia rosea, còn gọi chuông hồng) nở hoa hồng phấn hình kèn phủ kín tán vào mùa khô, trông rất lãng mạn. Tán thoáng, dáng đẹp, hợp đường phố, quảng trường, khu đô thị mới. Lá rụng ngắn trước mùa hoa."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Tabebuia_rosea_at_Taman_Sejati%2C_Sandakan_20250610_132403.jpg/960px-Tabebuia_rosea_at_Taman_Sejati%2C_Sandakan_20250610_132403.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Kèn hồng nở kín tán ở một vòng xoay — hoa hồng phấn mùa khô."}, {"type": "h2", "text": "Giáng hương — tán tròn, hoa vàng thơm"}, {"type": "p", "text": "[Giáng hương](/san-pham/giang-huong) (chi Pterocarpus, họ Đậu) có tán tròn rộng, lá xanh mướt, hoa vàng nhỏ nở rộ trong vài ngày, thơm nhẹ. Gỗ quý, cây bền, sống lâu. Hợp đường phố rộng, công viên, khuôn viên cơ quan."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Narra_tree_%28Pterocarpus_indicus%29.jpg/960px-Narra_tree_%28Pterocarpus_indicus%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Cây giáng hương (Pterocarpus) trưởng thành — tán tròn, thân thẳng."}, {"type": "h2", "text": "Dầu rái — cây cao, thân thẳng"}, {"type": "p", "text": "[Dầu rái](/san-pham/dau-rai) (Dipterocarpus alatus) là cây bản địa Nam Bộ, thân thẳng tắp, có thể cao trên 30m, tán gọn ở trên cao. Rất bền, chịu gió tốt khi trưởng thành, hợp đại lộ, công viên lớn, khuôn viên rộng. Không hợp hẻm nhỏ hay sát nhà thấp tầng vì cây rất cao."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Batang_pokok_keruing_kipas_%28dipterocarpus_costulatus%29_%282%29_%E2%80%93_TER_Sg._Pandan%2C_Kuantan_IMG20250727.jpg/960px-Batang_pokok_keruing_kipas_%28dipterocarpus_costulatus%29_%282%29_%E2%80%93_TER_Sg._Pandan%2C_Kuantan_IMG20250727.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Thân cây họ Dầu thẳng tắp vươn cao — đặc trưng của dầu rái khi trưởng thành."}, {"type": "h2", "text": "Bàng Đài Loan — tán tầng, lá nhỏ"}, {"type": "p", "text": "[Bàng Đài Loan](/san-pham/bang-dai-loan) (Terminalia mantaly, bàng lá nhỏ) có cành mọc thành tầng ngang đều đặn như chiếc ô xếp tầng, lá nhỏ li ti. Dáng rất gọn và hiện đại, hợp khu đô thị, sân nhà phố, bãi xe, mặt tiền cửa hàng. Lá nhỏ rụng ít gây bít cống hơn bàng ta lá to."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/HK_SKD_%E6%97%A5%E5%87%BA%E5%BA%B7%E5%9F%8E_Lohas_Park_Road_MALIBU_footbridge_view_green_trees_April_2026_N13P_01.jpg/960px-HK_SKD_%E6%97%A5%E5%87%BA%E5%BA%B7%E5%9F%8E_Lohas_Park_Road_MALIBU_footbridge_view_green_trees_April_2026_N13P_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Bàng Đài Loan cành mọc thành tầng ngang — dáng gọn, hợp khu đô thị."}, {"type": "h2", "text": "Cau trắng — cho lối đi, hàng rào"}, {"type": "p", "text": "[Cau trắng](/san-pham/cau-trang) (Adonidia merrillii, cau Manila) thân trắng xám, tán lá gọn trên ngọn, không cho bóng mát rộng nhưng tạo hàng thẳng đẹp. Hợp lối đi, viền sân, hồ bơi, resort, nơi cần cây đứng không chiếm chỗ."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Flore_de_Tartane_%28La_Trinit%C3%A9%2C_Martinique%29_-_09.jpg/960px-Flore_de_Tartane_%28La_Trinit%C3%A9%2C_Martinique%29_-_09.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Cau trắng còn nhỏ — thân thẳng, tán gọn, hợp trồng hàng dọc lối đi."}, {"type": "h2", "text": "Bảng so sánh 7 loại cây công trình"}, {"type": "table", "rows": [["Cây", "Tán", "Rễ", "Hoa", "Hợp nhất cho"], ["Bằng lăng", "Trung bình, gọn", "Ăn sâu", "Tím, đầu hè", "Đường nội bộ, sân trường"], ["Phượng vĩ", "Rất rộng, hình dù", "Lan ngang", "Đỏ cam, mùa hè", "Sân trường, công viên rộng"], ["Kèn hồng", "Thoáng", "Trung bình", "Hồng phấn, mùa khô", "Đường phố, quảng trường"], ["Giáng hương", "Tròn rộng", "Trung bình", "Vàng, thơm", "Đường lớn, công viên"], ["Dầu rái", "Cao, gọn trên ngọn", "Ăn sâu", "Không nổi bật", "Đại lộ, khuôn viên lớn"], ["Bàng Đài Loan", "Tầng ngang", "Trung bình", "Không nổi bật", "Khu đô thị, bãi xe"], ["Cau trắng", "Gọn trên ngọn", "Chùm, gọn", "Không nổi bật", "Lối đi, hồ bơi, resort"]]}, {"type": "h2", "text": "Chăm cây công trình mới trồng"}, {"type": "list", "items": ["**Tưới đẫm 1 lần/ngày trong 1–2 tháng đầu**, sau khi cây bén rễ thì tưới khi đất khô.", "**Chống cây bằng 3 cọc** cho đến khi rễ bám chắc (thường hết mùa mưa đầu tiên), tránh gió làm nghiêng gốc.", "**Hố trồng rộng gấp 2 bầu cây**, lót đất tốt và phân hữu cơ hoai.", "**Tỉa tạo tán** từ năm đầu để định hướng cành chính, nhất là phượng vĩ — cây được tỉa sớm ít gãy cành hơn khi trưởng thành."], "ordered": false}, {"type": "note", "title": "Cây công trình số lượng lớn", "text": "Giá cây công trình phụ thuộc đường kính gốc, chiều cao, bầu đất và số lượng. Đơn vị thi công, chủ đầu tư nên gửi danh sách cây theo bảng khối lượng để shop báo giá sỉ và kiểm tra cây có sẵn tại vườn."}, {"type": "products", "title": "Cây công trình tại vườn", "slugs": ["bang-lang", "phuong-vi", "ken-hong", "giang-huong", "dau-rai", "bang-dai-loan"]}, {"type": "p", "text": "Có bảng khối lượng hoặc danh sách cây? [Gửi yêu cầu báo giá sỉ](/bao-gia-si) hoặc xem thêm chương trình dành cho [đối tác cảnh quan, công trình](/doi-tac)."}]'::jsonb, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Delonix_regia_Sunbury_Street_Geebung_P1130442.jpg/960px-Delonix_regia_Sunbury_Street_Geebung_P1130442.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 5, '[]'::jsonb, '["cây công trình", "cây bóng mát", "cây đường phố", "cảnh quan"]'::jsonb, 'So sánh cây công trình bằng lăng, phượng vĩ, kèn hồng, giáng hương, dầu rái, bàng Đài Loan, cau trắng: tán, rễ, hoa, hợp đường phố, sân trường, khu dân cư.'),
('cay-ban-cong-nang-gat', 'Cây trồng ban công nắng gắt hướng Tây: chọn cây nào để không cháy lá?', 'Ban công hướng Tây, hướng Nam nắng gắt từ trưa tới chiều, gió lớn, tường gạch hắt nóng. Nhiều cây đẹp đem ra là cháy lá sau vài ngày. Bài này chia ban công thành 3 kiểu nắng và chọn cây chịu được từng kiểu.', '[{"type": "p", "text": "Ban công là nơi trồng cây \"khó\" nhất trong nhà phố, chung cư ở miền Nam: nắng chiếu thẳng nhiều giờ, gió mạnh ở tầng cao, chậu đặt trên nền gạch hấp nóng, đất khô rất nhanh. Cây trong nhà như trầu bà, đuôi công đem ra ban công nắng chỉ vài ngày là cháy lá."}, {"type": "p", "text": "Bí quyết là **xác định đúng ban công nhà mình thuộc kiểu nắng nào**, rồi chọn cây hợp kiểu đó."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/QXRZLX36A5.jpg", "caption": "Ban công nhỏ với chậu cây đặt dọc lan can — ban công tầng cao thường gió mạnh, đất khô nhanh."}, {"type": "h2", "text": "Ban công nhà bạn thuộc kiểu nào?"}, {"type": "p", "text": "Đếm số giờ nắng chiếu trực tiếp vào chỗ đặt chậu trong một ngày nắng:"}, {"type": "table", "rows": [["Kiểu", "Giờ nắng trực tiếp", "Thường gặp ở", "Nhóm cây hợp"], ["Nắng gắt", "Trên 6 giờ, có nắng chiều", "Hướng Tây, Tây Nam", "Cây ưa nắng: hoa hồng, tắc, ngọc bích, tùng thơm"], ["Nắng sáng", "3–5 giờ, chủ yếu buổi sáng", "Hướng Đông, Đông Nam", "Hoa mai địa thảo, tulip Thái, lan chi"], ["Ít nắng", "Dưới 2 giờ hoặc có mái che", "Hướng Bắc, ban công có mái", "Lưỡi hổ, dương xỉ, cây trong nhà chịu bóng"]]}, {"type": "h2", "text": "Cây cho ban công nắng gắt"}, {"type": "h3", "text": "Hoa hồng"}, {"type": "p", "text": "[Hoa hồng](/san-pham/hoa-hong) cần nắng trực tiếp **ít nhất 6 giờ mỗi ngày** — thiếu nắng cây ít hoa, dễ nấm bệnh. Ban công hướng Tây chính là nơi hồng ra hoa đẹp nhất, miễn là bạn tưới đủ. Tưới gốc mỗi sáng, tránh tưới lên lá và hoa để giảm bệnh [đốm lá](/benh-cay/dom-la-nam) và [phấn trắng](/benh-cay/phan-trang). Hồng thuộc loại cần chăm kỹ: tỉa hoa tàn, bón phân định kỳ."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Flower_in_Mongolia.jpg/960px-Flower_in_Mongolia.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Hoa hồng trồng chậu — cần nắng trực tiếp ít nhất 6 giờ mỗi ngày."}, {"type": "h3", "text": "Tắc cẩm thạch Thái"}, {"type": "p", "text": "[Tắc cẩm thạch Thái](/san-pham/tac-cam-thach-thai) có lá đốm trắng xanh, ra hoa trắng thơm và trái quanh năm, chín vàng — vừa làm cảnh vừa lấy trái, chưng Tết rất đẹp. Cần nắng toàn phần ít nhất 6 giờ/ngày, tưới mỗi ngày mùa nắng, giữ ẩm đều khi đang ra hoa nuôi trái."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Limau_Kesturi_1.jpg/960px-Limau_Kesturi_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Cây tắc (họ cam chanh) có trái — ưa nắng toàn phần."}, {"type": "h3", "text": "Ngọc bích"}, {"type": "p", "text": "[Ngọc bích](/san-pham/ngoc-bich) (Crassula ovata) là cây mọng nước, rất thích nắng sáng và chịu nóng tốt. Lá tròn mọng, thân hóa gỗ. Tưới rất ít — khoảng một lần mỗi tuần, đất khô hẳn mới tưới. Lưu ý: nắng chiều quá gắt mùa khô có thể làm lá đỏ mép, đó là phản ứng tự nhiên, không phải bệnh."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Crassula_-_Talcott_Greenhouse_-_Mount_Holyoke_College_-_DSC04544.JPG/960px-Crassula_-_Talcott_Greenhouse_-_Mount_Holyoke_College_-_DSC04544.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Ngọc bích lớn trồng chậu — cây mọng nước chịu nắng, chịu nóng."}, {"type": "h3", "text": "Tùng thơm"}, {"type": "p", "text": "[Tùng thơm](/san-pham/tung-thom) (tùng chanh, Cupressus macrocarpa ''Goldcrest'') có dáng tháp nhọn, lá vàng chanh, vò lá có mùi thơm như chanh. Chịu nắng nhẹ đến nắng trực tiếp, cần tưới mỗi ngày mùa nắng — **không được để khô kiệt**, lá sẽ nâu và không xanh lại."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/%E9%B3%B3%E9%B3%B4%E8%BB%8A%E7%AB%99%E5%85%A7%E6%AA%B8%E6%AA%AC%E6%9D%89.jpg/960px-%E9%B3%B3%E9%B3%B4%E8%BB%8A%E7%AB%99%E5%85%A7%E6%AA%B8%E6%AA%AC%E6%9D%89.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Tùng thơm (lemon cypress) trồng hàng trong bồn — dáng tháp, lá vàng chanh."}, {"type": "h3", "text": "Lưỡi hổ"}, {"type": "p", "text": "[Lưỡi hổ](/san-pham/luoi-ho) không chỉ là cây trong nhà — cây chịu được nắng nhẹ và rất chịu hạn. Ban công nắng gắt quá thì lá có thể vàng mép; đặt ở chỗ có bóng một phần buổi chiều là đẹp nhất."}, {"type": "h2", "text": "Cây cho ban công nắng sáng"}, {"type": "list", "items": ["[Mai địa thảo](/san-pham/mai-dia-thao) (Impatiens) — hoa nhiều màu nở liên tục, ưa nắng nhẹ buổi sáng hoặc bóng râm một phần; nắng gắt buổi trưa làm héo lá. Giữ đất ẩm đều.", "[Tulip Thái](/san-pham/tulip-thai) (Curcuma alismatifolia) — hoa hồng tím dạng tulip vào mùa mưa, nắng nhẹ đến nắng sáng; mùa khô củ nghỉ thì giảm tưới.", "[Lan chi](/san-pham/lan-chi) — treo giỏ trên ban công nắng sáng rất đẹp, lá càng sọc rõ khi đủ sáng."], "ordered": false}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/Solenostemon_scutellarioides_cultivars_public_domain_IMG_4814.jpg/960px-Solenostemon_scutellarioides_cultivars_public_domain_IMG_4814.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Bồn hoa mai địa thảo nhiều màu — ưa nắng sáng, giữ đất ẩm đều."}, {"type": "h2", "text": "Chống nóng cho chậu ban công"}, {"type": "p", "text": "Nắng gắt không chỉ làm cháy lá mà còn **nung nóng chậu**, làm rễ \"chín\" bên trong. Một vài cách đơn giản:"}, {"type": "list", "items": ["**Kê chậu lên giá hoặc đế gỗ**, không đặt thẳng xuống nền gạch nóng.", "**Chọn chậu sáng màu, chậu đất nung, chậu nhựa dày** thay vì chậu nhựa đen mỏng hấp nhiệt.", "**Phủ mặt chậu** bằng xơ dừa, vỏ trấu, sỏi để giữ ẩm, giảm bốc hơi.", "**Tưới sáng sớm** (trước 8 giờ) hoặc chiều mát. Tránh tưới giữa trưa khi đất đang nóng.", "**Dùng lưới che nắng 30–50%** cho ban công hướng Tây vào mùa khô (tháng 3–5).", "**Gom chậu gần nhau**: cây đứng thành cụm giữ ẩm cho nhau tốt hơn cây đứng riêng."], "ordered": true}, {"type": "note", "title": "Ban công tầng cao gió mạnh", "text": "Chọn chậu nặng, đáy rộng để không bị gió lật; cột cây cao vào lan can. Không treo chậu nặng ra ngoài lan can — rất nguy hiểm cho người đi bên dưới."}, {"type": "products", "title": "Cây ban công tại vườn", "slugs": ["hoa-hong", "tac-cam-thach-thai", "ngoc-bich", "tung-thom", "mai-dia-thao", "luoi-ho"]}, {"type": "p", "text": "Ban công ít nắng hơn? Xem [cây trồng trong nhà thiếu sáng](/goc-cham-cay/cay-trong-nha-thieu-sang) để chọn cây chịu bóng."}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/QXRZLX36A5.jpg', 4, '[]'::jsonb, '["ban công", "cây chịu nắng", "hướng tây", "chung cư"]'::jsonb, 'Cây trồng ban công nắng gắt, hướng Tây: hoa hồng, tắc cẩm thạch, ngọc bích, tùng thơm, lưỡi hổ… cách chọn theo giờ nắng, cách tưới và chống nóng cho chậu.'),
('cay-trong-nha-thieu-sang', 'Cây trồng trong nhà thiếu sáng: 6 cây sống khỏe ở góc tối và cách "đo" ánh sáng tại nhà', 'Nhà phố hẹp, chung cư ít cửa sổ, góc cầu thang, nhà vệ sinh — chỗ nào cũng muốn có cây nhưng ánh sáng rất ít. Bài này chỉ cách tự đo ánh sáng bằng mắt, chọn 6 cây chịu bóng tốt nhất và mẹo giúp cây sống lâu ở góc tối.', '[{"type": "p", "text": "Câu hỏi shop nghe nhiều nhất từ khách ở chung cư và nhà phố là: \"Nhà em ít nắng lắm, trồng cây gì được?\". Tin tốt là có khá nhiều cây chịu bóng. Tin chưa tốt là **không cây nào sống mãi trong bóng tối hoàn toàn** — cây nào cũng cần một ít ánh sáng để quang hợp."}, {"type": "p", "text": "Vì vậy bước đầu tiên không phải chọn cây, mà là biết góc nhà mình \"tối\" tới mức nào."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/06OAHLI7B4.jpg", "caption": "Cây nhỏ đặt bên cửa sổ có rèm — ánh sáng tán xạ qua rèm là đủ cho phần lớn cây chịu bóng."}, {"type": "h2", "text": "Tự đo ánh sáng bằng mắt và bóng tay"}, {"type": "p", "text": "Không cần máy đo. Vào khoảng 10 giờ sáng một ngày trời quang, đứng ở chỗ định đặt cây và giơ bàn tay cách tờ giấy trắng khoảng 30cm:"}, {"type": "table", "rows": [["Bóng tay trên giấy", "Mức sáng", "Cây hợp"], ["Bóng đậm, viền sắc nét", "Sáng mạnh (có nắng chiếu)", "Cây ưa nắng: ngọc bích, hoa hồng, tùng thơm"], ["Bóng rõ nhưng viền mờ", "Sáng tán xạ", "Hầu hết cây trong nhà"], ["Bóng rất mờ, khó thấy", "Thiếu sáng", "Cây chịu bóng trong bài này"], ["Không thấy bóng", "Rất tối", "Chỉ lưỡi hổ — và cần luân phiên ra chỗ sáng"]]}, {"type": "p", "text": "Một mẹo khác: ánh sáng giảm rất nhanh khi đi xa cửa sổ. Chỉ cách cửa sổ 3m, cường độ ánh sáng đã giảm còn một phần nhỏ so với sát cửa. Dời chậu lại gần cửa sổ 1m đôi khi có tác dụng hơn mọi loại phân bón."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/DXLNXCCDGP.jpg", "caption": "Các chậu cây đặt trên bậu cửa sổ — chỗ sáng nhất trong nhà."}, {"type": "h2", "text": "6 cây chịu bóng tốt nhất"}, {"type": "h3", "text": "1. Lưỡi hổ — sống được ở góc tối nhất"}, {"type": "p", "text": "[Lưỡi hổ](/san-pham/luoi-ho) là cây \"cứu cánh\" cho góc tối: chịu bóng râm, chịu đèn điện, tưới 7–10 ngày một lần. Trong điều kiện thiếu sáng, cây gần như ngừng lớn nhưng vẫn giữ lá xanh rất lâu. Lưu ý: góc tối thì đất khô chậm, nên **càng tối càng phải tưới thưa**."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Snake_plant_Sansevieria_growing_in_a_pot_portrait.jpg/960px-Snake_plant_Sansevieria_growing_in_a_pot_portrait.jpg", "caption": "Lưỡi hổ trồng chậu — cây chịu bóng bền nhất."}, {"type": "h3", "text": "2. Bạch mã"}, {"type": "p", "text": "[Bạch mã](/san-pham/bach-ma-hoang-tu) chịu bóng râm tốt, thân trắng ngà nhìn sáng sủa, hợp hành lang, góc phòng khách xa cửa sổ. Tưới khi đất mặt khô 2–3cm."}, {"type": "h3", "text": "3. Vạn niên thanh"}, {"type": "p", "text": "[Vạn niên thanh](/san-pham/van-nien-thanh) (Dieffenbachia) lá to loang trắng, chịu bóng tốt, cao 40cm–1m. Lá loang trắng giúp góc tối trông sáng hơn hẳn so với cây lá xanh đậm."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Dieffenbachia_seguine_photography.jpg/960px-Dieffenbachia_seguine_photography.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Vạn niên thanh lá loang trắng — làm góc tối trông sáng sủa hơn."}, {"type": "h3", "text": "4. Dạ lan thanh"}, {"type": "p", "text": "[Dạ lan thanh](/san-pham/da-lan-thanh) xanh tốt quanh năm, chịu bóng râm, có cỡ cao 70cm–1m cho góc phòng lớn. Giữ đất hơi ẩm, tưới 2–3 lần mỗi tuần."}, {"type": "h3", "text": "5. Lan ý"}, {"type": "p", "text": "[Lan ý](/san-pham/lan-y) chịu bóng và chịu đèn văn phòng; ở chỗ quá tối cây vẫn xanh nhưng ít ra hoa. Muốn có hoa, đặt cây chỗ sáng tán xạ hơn. Lá rũ là dấu hiệu cần tưới — rất dễ chăm cho người hay quên."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Spathiphyllum_friedrichsthalii_%28Martinique%29_-_02.jpg/960px-Spathiphyllum_friedrichsthalii_%28Martinique%29_-_02.jpg", "caption": "Hoa lan ý — ở chỗ đủ sáng tán xạ cây ra hoa nhiều đợt."}, {"type": "h3", "text": "6. Ngân hậu"}, {"type": "p", "text": "[Ngân hậu](/san-pham/ngan-hau) lá ánh bạc, chịu bóng tốt, cỡ 30–50cm vừa kệ tivi, tủ giày. Sắc bạc phản chiếu ánh đèn, góc tối nhìn bớt u ám."}, {"type": "h2", "text": "Những cây KHÔNG nên đặt chỗ thiếu sáng"}, {"type": "list", "items": ["**Ngọc bích, sen đá, xương rồng**: cây mọng nước cần nắng; thiếu sáng thân vươn dài, lá thưa, mềm nhũn.", "**Hoa hồng, mai địa thảo, tắc**: cây ra hoa, ra trái cần nắng trực tiếp nhiều giờ.", "**Tùng thơm**: thiếu sáng lá rụng, nâu dần.", "**Giống lá đỏ, lá vàng** (trầu bà đế vương đỏ/vàng, vạn lộc): sống được nhưng lá mới sẽ nhạt màu, xanh dần."], "ordered": false}, {"type": "h2", "text": "Mẹo chăm cây ở góc tối"}, {"type": "list", "items": ["**Tưới ít hơn bạn nghĩ.** Thiếu sáng, cây dùng nước chậm, đất khô chậm. Úng rễ là nguyên nhân chết số một của cây ở góc tối, không phải thiếu sáng.", "**Không bón phân nhiều.** Cây lớn chậm không cần nhiều dinh dưỡng; bón dư dễ [cháy rễ](/benh-cay/chay-re-do-phan).", "**Luân phiên 2 chậu**: một chậu ở góc tối, một chậu ở chỗ sáng; đổi chỗ mỗi 2–4 tuần. Cách này giữ được cả hai cây đẹp lâu dài.", "**Bật đèn**: đèn LED trắng bật 8–10 giờ mỗi ngày giúp cây chịu bóng sống tốt ở phòng không cửa sổ. Đèn càng gần cây (30–60cm) càng hiệu quả.", "**Lau lá thường xuyên**: lá sạch bụi hấp thụ được nhiều ánh sáng hơn.", "**Xoay chậu** mỗi tuần để cây không nghiêng về phía nguồn sáng."], "ordered": true}, {"type": "note", "title": "Nhà vệ sinh không cửa sổ", "text": "Không nên để cây ở đây lâu dài kể cả lưỡi hổ. Nếu muốn có cây, hãy luân phiên: 1 tuần trong nhà vệ sinh, 1–2 tuần ra chỗ sáng."}, {"type": "products", "title": "Cây chịu bóng tại vườn", "slugs": ["luoi-ho", "bach-ma-hoang-tu", "van-nien-thanh", "da-lan-thanh", "lan-y", "ngan-hau"]}, {"type": "p", "text": "Ban công hay cửa sổ nhà bạn có nhiều nắng? Xem bài [cây trồng ban công nắng gắt](/goc-cham-cay/cay-ban-cong-nang-gat)."}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/06OAHLI7B4.jpg', 4, '[]'::jsonb, '["cây trong nhà", "thiếu sáng", "chịu bóng", "chung cư"]'::jsonb, 'Cây trồng trong nhà thiếu sáng, góc tối: lưỡi hổ, bạch mã, vạn niên thanh, dạ lan thanh, lan ý, ngân hậu. Cách đo ánh sáng tại nhà và mẹo chăm cây ở góc tối.'),
('chon-cay-theo-menh-ngu-hanh', 'Chọn cây cảnh hợp mệnh Kim, Mộc, Thủy, Hỏa, Thổ theo màu lá và ý nghĩa dân gian', 'Nhiều người chọn cây theo mệnh để đặt bàn làm việc, tặng người thân hay chưng trong nhà. Bài này giải thích cách dân gian ghép cây với ngũ hành theo màu sắc, gợi ý cây hợp từng mệnh và nhắc những điều quan trọng hơn cả mệnh khi chọn cây.', '[{"type": "p", "text": "Chọn cây theo mệnh là thói quen của rất nhiều gia đình Việt, nhất là khi mua cây đặt bàn làm việc, cửa hàng hay làm quà khai trương, tân gia. Bài này tổng hợp **cách dân gian thường ghép cây với ngũ hành** để bạn tham khảo. Đây là quan niệm văn hóa, không phải quy luật khoa học — cây đẹp, khỏe, hợp chỗ đặt vẫn là điều quan trọng nhất."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Lucky_Cat_%28Unsplash%29.jpg/960px-Lucky_Cat_%28Unsplash%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Chậu lưỡi hổ đặt cạnh tượng mèo may mắn — cây cảnh thường được chọn kèm ý nghĩa phong thủy."}, {"type": "h2", "text": "Cây được ghép với mệnh như thế nào?"}, {"type": "p", "text": "Cách phổ biến nhất là dựa vào **màu sắc chủ đạo** của lá, hoa và chậu, theo màu đại diện của từng hành:"}, {"type": "table", "rows": [["Hành", "Màu đại diện", "Màu tương sinh (được nâng đỡ)"], ["Kim", "Trắng, bạc, xám", "Vàng, nâu đất (Thổ sinh Kim)"], ["Mộc", "Xanh lá", "Đen, xanh nước biển (Thủy sinh Mộc)"], ["Thủy", "Đen, xanh nước biển", "Trắng, bạc (Kim sinh Thủy)"], ["Hỏa", "Đỏ, hồng, tím", "Xanh lá (Mộc sinh Hỏa)"], ["Thổ", "Vàng, nâu đất", "Đỏ, hồng (Hỏa sinh Thổ)"]]}, {"type": "p", "text": "Vì vậy một cây có thể hợp nhiều mệnh: cây lá xanh hợp Mộc (bản mệnh) và cũng được xem là tốt cho Hỏa (Mộc sinh Hỏa). Chậu cũng góp phần: chậu trắng, bạc thêm hành Kim; chậu đất nung nâu thêm hành Thổ."}, {"type": "h2", "text": "Cây hợp mệnh Kim"}, {"type": "p", "text": "Người mệnh Kim hợp cây lá trắng, bạc, loang trắng, hoặc cây có màu vàng, nâu (Thổ sinh Kim):"}, {"type": "list", "items": ["[Lưỡi hổ](/san-pham/luoi-ho) — lá nhọn đứng thẳng, viền vàng; dân gian tin cây giúp xua điều xấu. Hợp Kim, Thủy.", "[Bạch mã](/san-pham/bach-ma-hoang-tu) — thân trắng ngà, ý nghĩa thành đạt, thăng tiến.", "[Ngân hậu](/san-pham/ngan-hau) — lá ánh bạc, sang trọng, bình an.", "[Ngọc ngân](/san-pham/ngoc-ngan) — lá đốm trắng, tình yêu bền chặt.", "[Tắc cẩm thạch Thái](/san-pham/tac-cam-thach-thai) — lá loang trắng, trái chín vàng; hợp Kim, Thổ."], "ordered": false}, {"type": "h2", "text": "Cây hợp mệnh Mộc"}, {"type": "p", "text": "Mệnh Mộc hợp cây lá xanh tươi — đây là nhóm có nhiều lựa chọn nhất:"}, {"type": "list", "items": ["[Trầu bà đế vương xanh](/san-pham/trau-ba-de-vuong-xanh) — lá to bóng, tượng trưng thịnh vượng, thăng tiến.", "[Vạn niên thanh](/san-pham/van-nien-thanh) — \"xanh tươi muôn năm\", sức khỏe, trường thọ.", "[Dạ lan thanh](/san-pham/da-lan-thanh) — xanh quanh năm, sung túc.", "[Dương xỉ](/san-pham/duong-xi) — bình yên, che chở.", "[Ngọc bích](/san-pham/ngoc-bich) — lá tròn như đồng xu, tiền tài.", "[Tùng thơm](/san-pham/tung-thom) — bền bỉ, trường thọ."], "ordered": false}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09417.jpg/960px-Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09417.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Lá xanh bóng của trầu bà — nhóm cây lá xanh được xem là hợp mệnh Mộc."}, {"type": "h2", "text": "Cây hợp mệnh Thủy"}, {"type": "p", "text": "Mệnh Thủy hợp cây có màu trắng, bạc (Kim sinh Thủy) và cây gắn với nước. Theo dữ liệu cây tại vườn, nhóm hợp Thủy trùng với nhóm Kim: lưỡi hổ, bạch mã, ngân hậu, ngọc ngân. Chậu màu xanh dương, đen hoặc cây trồng thủy sinh trong bình nước cũng được chọn cho mệnh Thủy."}, {"type": "h2", "text": "Cây hợp mệnh Hỏa"}, {"type": "p", "text": "Mệnh Hỏa hợp cây lá đỏ, hồng, tím và cả cây lá xanh (Mộc sinh Hỏa):"}, {"type": "list", "items": ["[Phú quý](/san-pham/phu-quy) — lá viền, gân đỏ hồng, giàu sang. Hợp Hỏa, Thổ.", "[Vạn lộc](/san-pham/van-loc) — lá hồng đỏ, vạn sự may mắn. Hợp Hỏa, Thổ.", "[Trầu bà đế vương đỏ](/san-pham/trau-ba-de-vuong-do) — lá đỏ rượu vang, may mắn, thịnh vượng. Hợp Hỏa, Thổ.", "[Đuôi công tím](/san-pham/duoi-cong-tim) — mặt dưới lá tím, sung túc, may mắn.", "[Môn quan âm](/san-pham/mon-quan-am) — lá vươn thẳng gân bạc, may mắn, tài lộc."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Aglaonema_commutatum_-_Saigon_Zoo_and_Botanical_Gardens_-_Ho_Chi_Minh_City%2C_Vietnam_-_DSC01286.JPG/960px-Aglaonema_commutatum_-_Saigon_Zoo_and_Botanical_Gardens_-_Ho_Chi_Minh_City%2C_Vietnam_-_DSC01286.JPG", "caption": "Aglaonema lá đỏ hồng — sắc đỏ được dân gian xem là hợp mệnh Hỏa."}, {"type": "h2", "text": "Cây hợp mệnh Thổ"}, {"type": "p", "text": "Mệnh Thổ hợp cây có màu vàng, nâu đất và màu đỏ (Hỏa sinh Thổ): phú quý, vạn lộc, trầu bà đế vương đỏ, tắc cẩm thạch Thái (trái chín vàng). Chậu đất nung, chậu gốm màu nâu cũng tăng hành Thổ."}, {"type": "h2", "text": "Bảng tổng hợp cây tại vườn theo mệnh"}, {"type": "table", "rows": [["Cây", "Màu chủ đạo", "Hợp mệnh"], ["Lưỡi hổ, bạch mã, ngân hậu, ngọc ngân", "Trắng, bạc, loang trắng", "Kim, Thủy"], ["Phú quý, vạn lộc, trầu bà đế vương đỏ", "Đỏ, hồng", "Hỏa, Thổ"], ["Trầu bà đế vương xanh, vạn niên thanh, dạ lan thanh", "Xanh lá", "Mộc, Hỏa"], ["Dương xỉ, tùng thơm, ngọc bích, đuôi công", "Xanh lá", "Mộc, Hỏa"], ["Tắc cẩm thạch Thái", "Lá loang trắng, trái vàng", "Kim, Thổ"]]}, {"type": "h2", "text": "Điều quan trọng hơn cả mệnh"}, {"type": "p", "text": "Một cây hợp mệnh mà đặt sai chỗ, vài tuần đã vàng úa, thì chẳng mang lại may mắn gì. Khi chọn cây, hãy ưu tiên theo thứ tự:"}, {"type": "list", "items": ["**Hợp ánh sáng chỗ đặt** — cây ưa nắng không thể sống ở góc tối, cây chịu bóng sẽ cháy lá ngoài nắng.", "**Hợp thời gian chăm** — người bận nên chọn cây chịu khô như lưỡi hổ, ngọc bích.", "**An toàn cho người trong nhà** — nhà có trẻ nhỏ, thú cưng nên tránh cây có nhựa độc.", "**Sau đó mới đến màu sắc hợp mệnh.**"], "ordered": true}, {"type": "note", "title": "Cây héo, chết không phải \"điềm xấu\"", "text": "Cây chết gần như luôn do tưới sai, thiếu sáng hoặc sâu bệnh. Nếu cây bạn tặng hoặc đang trồng có dấu hiệu lạ, xem [thư viện bệnh cây](/benh-cay) hoặc nhắn shop ảnh cây để được hướng dẫn."}, {"type": "products", "title": "Cây phong thủy tại vườn", "slugs": ["luoi-ho", "bach-ma-hoang-tu", "phu-quy", "van-loc", "trau-ba-de-vuong-xanh", "trau-ba-de-vuong-do"]}, {"type": "p", "text": "Trên mỗi trang sản phẩm có mục **Ý nghĩa phong thủy** ghi mệnh hợp, vị trí đặt và ý nghĩa của từng cây. Bạn cũng có thể chọn mệnh trong [Tư vấn chọn cây](/tu-van-chon-cay) để được gợi ý cây hợp."}]'::jsonb, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Lucky_Cat_%28Unsplash%29.jpg/960px-Lucky_Cat_%28Unsplash%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 5, '[]'::jsonb, '["phong thủy", "hợp mệnh", "ngũ hành", "quà tặng"]'::jsonb, 'Chọn cây cảnh hợp mệnh Kim, Mộc, Thủy, Hỏa, Thổ theo màu lá: lưỡi hổ, bạch mã, phú quý, vạn lộc, trầu bà đế vương… cách ghép theo ngũ hành tương sinh.'),
('cay-canh-an-toan-tre-nho-thu-cung', 'Cây cảnh an toàn cho nhà có trẻ nhỏ, chó mèo — và những cây nên đặt xa tầm với', 'Mèo hay gặm lá, bé đang tuổi cái gì cũng cho vào miệng — vậy nhà mình trồng cây gì cho yên tâm? Bài này liệt kê cây không độc, cây độc nhẹ, cây cần đặt xa tầm với, kèm dấu hiệu khi bé hoặc thú cưng nhai phải lá và cách xử lý ban đầu.', '[{"type": "p", "text": "Rất nhiều cây cảnh trong nhà phổ biến có nhựa hoặc chất gây kích ứng. Phần lớn chỉ gây ngứa, rát miệng chứ không nguy hiểm đến tính mạng, nhưng với trẻ nhỏ và thú cưng — những \"thành viên\" hay tò mò cắn lá — thì vẫn nên biết rõ để chọn và đặt cây cho đúng."}, {"type": "p", "text": "Thông tin về độ an toàn trong bài dựa trên danh sách cây độc / không độc với chó mèo của Hiệp hội phòng chống ngược đãi động vật Hoa Kỳ (ASPCA) và tài liệu phổ biến về cây cảnh, khớp với mục \"An toàn thú cưng\" trên từng trang sản phẩm của shop."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/It%27s_snoozing_time.jpg/960px-It%27s_snoozing_time.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Mèo nằm ngủ cạnh các chậu cây — thú cưng hay gặm lá cây trong nhà."}, {"type": "h2", "text": "Nhóm 1: Cây không độc — yên tâm trồng"}, {"type": "h3", "text": "Đuôi công (Calathea)"}, {"type": "p", "text": "[Đuôi công tím](/san-pham/duoi-cong-tim), [đuôi công xanh](/san-pham/duoi-cong-xanh), [đuôi công phụng](/san-pham/duoi-phung) đều **an toàn với chó mèo**. Lá hoa văn đẹp, chịu bóng, cụp lá buổi tối — trẻ con rất thích quan sát. Cần giữ ẩm đều."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Goeppertia_makoyana_in_Guangzhou_Baiyun_International_Airport_T2.jpg/960px-Goeppertia_makoyana_in_Guangzhou_Baiyun_International_Airport_T2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Đuôi công trồng chậu — nhóm cây lá đẹp an toàn với chó mèo."}, {"type": "h3", "text": "Lan chi (cây dây nhện)"}, {"type": "p", "text": "[Lan chi](/san-pham/lan-chi) an toàn với chó mèo, rất dễ chăm, mọc nhanh. Lưu ý: mèo thường **rất thích nghịch lá lan chi** vì lá dài đung đưa — cây không độc nhưng có thể bị mèo cắn nát, nên treo cao nếu muốn giữ cây đẹp."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Spider_plant_with_plantlets_and_flowers.jpg/960px-Spider_plant_with_plantlets_and_flowers.jpg", "caption": "Lan chi với nhiều cây con rủ xuống — mèo thường thích vờn lá dài này."}, {"type": "h3", "text": "Dương xỉ"}, {"type": "p", "text": "[Dương xỉ](/san-pham/duong-xi) lá kiếm (Boston fern) an toàn với chó mèo. Hợp giỏ treo, kệ cao, cần đất luôn ẩm."}, {"type": "h3", "text": "Hoa hồng"}, {"type": "p", "text": "[Hoa hồng](/san-pham/hoa-hong) không độc với chó mèo, nhưng **gai nhọn** có thể làm trầy tay bé, chọc vào mắt thú cưng. Nên trồng ở ban công, sân vườn, không để ngang tầm trẻ chạy chơi."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/A_beautiful_red_rose_blooming_vibrantly.jpg/960px-A_beautiful_red_rose_blooming_vibrantly.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Hoa hồng không độc nhưng có gai — đặt ngoài tầm với của trẻ."}, {"type": "h2", "text": "Nhóm 2: Cây có nhựa gây ngứa — đặt xa tầm với"}, {"type": "p", "text": "Nhóm này chứa **tinh thể canxi oxalat** trong nhựa. Nhai phải lá gây ngứa, rát, sưng miệng, chảy nhiều nước bọt; chó mèo có thể nôn, bỏ ăn. Hiếm khi nguy hiểm, nhưng rất khó chịu. Bao gồm:"}, {"type": "list", "items": ["Nhóm Aglaonema: [phú quý](/san-pham/phu-quy), [vạn lộc](/san-pham/van-loc), [ngọc ngân](/san-pham/ngoc-ngan), [ngân hậu](/san-pham/ngan-hau), [bạch mã](/san-pham/bach-ma-hoang-tu).", "Trầu bà, trong đó có [trầu bà đế vương](/goc-cham-cay/phan-biet-cac-loai-trau-ba-de-vuong) các màu.", "[Môn quan âm](/san-pham/mon-quan-am), [môn melo](/san-pham/mon-melo).", "[Lan ý](/san-pham/lan-y), [dạ lan thanh](/san-pham/da-lan-thanh).", "[Vạn niên thanh](/san-pham/van-nien-thanh) (Dieffenbachia) — tên tiếng Anh \"dumb cane\" (cây câm) vì nhai phải lá có thể sưng lưỡi, khó nói tạm thời. Đây là loại **cần cẩn thận nhất** trong nhóm."], "ordered": false}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/HK_SSP_%E8%8D%94%E6%9E%9D%E8%A7%92_Lai_Chi_Kok_%E7%BE%8E%E5%AD%9A%E6%96%B0%E9%82%A8_Mei_Foo_Sun_Chuen_estate_park_flora_%E8%8A%B1%E8%91%89%E8%90%AC%E5%B9%B4%E9%9D%92_Dieffenbachia_green_leaves_April_2024_R12S_01.jpg/960px-HK_SSP_%E8%8D%94%E6%9E%9D%E8%A7%92_Lai_Chi_Kok_%E7%BE%8E%E5%AD%9A%E6%96%B0%E9%82%A8_Mei_Foo_Sun_Chuen_estate_park_flora_%E8%8A%B1%E8%91%89%E8%90%AC%E5%B9%B4%E9%9D%92_Dieffenbachia_green_leaves_April_2024_R12S_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Vạn niên thanh (Dieffenbachia) — lá đẹp nhưng nhựa gây sưng rát miệng nếu nhai phải."}, {"type": "h2", "text": "Nhóm 3: Độc nhẹ với chó mèo"}, {"type": "list", "items": ["[Lưỡi hổ](/san-pham/luoi-ho) — chứa saponin, chó mèo ăn phải có thể nôn, tiêu chảy nhẹ.", "[Ngọc bích](/san-pham/ngoc-bich) (Crassula ovata) — độc nhẹ với chó mèo, gây nôn, mệt.", "Cây họ cam chanh như [tắc cẩm thạch Thái](/san-pham/tac-cam-thach-thai) — lá, vỏ có tinh dầu, ASPCA xếp vào nhóm gây hại cho chó mèo nếu ăn nhiều. Trái tắc vẫn dùng bình thường cho người."], "ordered": false}, {"type": "h2", "text": "Bảng tra nhanh"}, {"type": "table", "rows": [["Cây", "Chó mèo", "Ghi chú"], ["Đuôi công các loại", "An toàn", "Giữ ẩm đều"], ["Lan chi", "An toàn", "Mèo hay vờn, nên treo cao"], ["Dương xỉ", "An toàn", "Cần ẩm"], ["Hoa hồng", "An toàn", "Có gai"], ["Lưỡi hổ", "Độc nhẹ", "Saponin"], ["Ngọc bích", "Độc nhẹ", "—"], ["Phú quý, vạn lộc, ngọc ngân, ngân hậu, bạch mã", "Gây ngứa, độc nếu nhai", "Canxi oxalat"], ["Trầu bà, môn, lan ý, dạ lan thanh", "Gây ngứa, độc nếu nhai", "Canxi oxalat"], ["Vạn niên thanh", "Gây sưng rát mạnh", "Đặt cao, tránh xa trẻ"]]}, {"type": "h2", "text": "Đặt cây sao cho an toàn"}, {"type": "list", "items": ["**Kệ cao trên 1,2m** cho cây nhóm 2 và 3 — ngoài tầm với của trẻ dưới 5 tuổi và chó. Với mèo (leo trèo giỏi), dùng giỏ treo trần hoặc phòng mèo không vào.", "**Không để lá rụng nằm trên sàn** — nhặt lá vàng, lá cắt tỉa ngay.", "**Rửa tay sau khi cắt tỉa** cây có nhựa, không dụi mắt.", "**Dạy trẻ** \"lá cây để ngắm, không để ăn\" từ sớm.", "**Cho mèo cỏ riêng**: trồng một khay cỏ lúa mì / cỏ mèo, mèo sẽ ít gặm cây cảnh hơn."], "ordered": true}, {"type": "note", "title": "Nếu bé hoặc thú cưng nhai phải lá", "text": "Lau sạch miệng, cho bé súc miệng hoặc uống vài ngụm nước, KHÔNG cố gây nôn. Giữ lại mẫu lá hoặc chụp ảnh cây để báo bác sĩ. Đưa bé đến cơ sở y tế ngay nếu sưng môi lưỡi, khó thở, nôn nhiều — trường hợp khẩn cấp gọi 115. Với chó mèo, liên hệ bác sĩ thú y."}, {"type": "products", "title": "Cây an toàn với chó mèo", "slugs": ["duoi-cong-tim", "duoi-cong-xanh", "duoi-phung", "lan-chi", "duong-xi", "hoa-hong"]}, {"type": "p", "text": "Muốn biết chi tiết từng cây, xem mục **An toàn thú cưng** trong bảng thông số ở mỗi trang sản phẩm."}]'::jsonb, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/It%27s_snoozing_time.jpg/960px-It%27s_snoozing_time.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 4, '[]'::jsonb, '["an toàn thú cưng", "trẻ nhỏ", "cây không độc", "chó mèo"]'::jsonb, 'Cây cảnh an toàn cho trẻ nhỏ, chó mèo: đuôi công, lan chi, dương xỉ, hoa hồng. Cây độc cần tránh: trầu bà, môn, lan ý, vạn niên thanh, lưỡi hổ, ngọc bích.'),
('chon-cay-qua-tang-khai-truong-tan-gia', 'Chọn cây cảnh làm quà: khai trương, tân gia, sinh nhật, thăng chức nên tặng cây gì?', 'Cây cảnh là món quà sống, càng để lâu càng đẹp — nhưng tặng sai cây thì người nhận khó chăm, vài tuần đã héo. Bài này gợi ý cây theo từng dịp, kèm cỡ cây, lời chúc hợp ý nghĩa và mẹo chọn sao cho người nhận dễ giữ cây lâu.', '[{"type": "p", "text": "So với hoa tươi chỉ giữ được vài ngày, một chậu cây cảnh có thể ở bên người nhận nhiều năm, mỗi lần nhìn lại nhớ tới người tặng. Nhưng cây là quà \"sống\": người nhận phải chăm được. Vì vậy chọn cây làm quà cần cân nhắc ba điều: **ý nghĩa, nơi đặt và khả năng chăm của người nhận**."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Aglaonema_%27Pink_Star%27.webp/960px-Aglaonema_%27Pink_Star%27.webp", "caption": "Aglaonema lá hồng — nhóm cây lá đỏ hồng là quà tặng phổ biến nhờ màu sắc tươi và ý nghĩa may mắn."}, {"type": "h2", "text": "Quà khai trương cửa hàng, công ty"}, {"type": "p", "text": "Khai trương cần cây **sắc đỏ, tên gọi tài lộc**, dáng đầy đặn để đặt ở quầy hoặc cửa ra vào:"}, {"type": "list", "items": ["[Phú quý](/san-pham/phu-quy) — tên gọi \"phú quý\" cùng lá viền đỏ là lựa chọn số một cho khai trương.", "[Vạn lộc](/san-pham/van-loc) — \"vạn sự may mắn, tài lộc dồi dào\", lá hồng đỏ rực.", "[Trầu bà đế vương đỏ](/san-pham/trau-ba-de-vuong-do) — cây lớn, lá to, hợp đặt sàn ở sảnh cửa hàng, văn phòng.", "[Ngọc bích](/san-pham/ngoc-bich) — lá tròn như đồng xu, hợp quầy thu ngân có ánh sáng tốt."], "ordered": false}, {"type": "p", "text": "**Cỡ cây**: quầy thu ngân, bàn lễ tân chọn 20–40cm; đặt sàn cạnh cửa chọn 50cm–1m hoặc loại 3 thân."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Aglaonema_commutatum_-_Saigon_Zoo_and_Botanical_Gardens_-_Ho_Chi_Minh_City%2C_Vietnam_-_DSC01286.JPG/960px-Aglaonema_commutatum_-_Saigon_Zoo_and_Botanical_Gardens_-_Ho_Chi_Minh_City%2C_Vietnam_-_DSC01286.JPG", "caption": "Aglaonema lá đỏ — sắc đỏ được chuộng cho quà khai trương."}, {"type": "h2", "text": "Quà tân gia"}, {"type": "p", "text": "Nhà mới cần cây **dễ chăm, hợp nhiều chỗ đặt**, ý nghĩa bình an, sum vầy:"}, {"type": "list", "items": ["[Vạn niên thanh](/san-pham/van-nien-thanh) — \"xanh tươi muôn năm\", sức khỏe, trường thọ.", "[Ngọc ngân](/san-pham/ngoc-ngan) — bình an, hạnh phúc bền chặt, hợp cặp vợ chồng trẻ.", "[Lưỡi hổ](/san-pham/luoi-ho) — dân gian tin giúp xua điều xấu, bảo vệ gia chủ; cực dễ chăm.", "[Lan ý](/san-pham/lan-y) — hoa trắng thanh khiết, hợp phòng khách."], "ordered": false}, {"type": "p", "text": "Nếu gia chủ có con nhỏ hoặc nuôi chó mèo, nên tặng cây an toàn như [đuôi công](/goc-cham-cay/phan-biet-cay-duoi-cong-calathea) hoặc lan chi."}, {"type": "h2", "text": "Quà thăng chức, chúc mừng sếp"}, {"type": "list", "items": ["[Bạch mã](/san-pham/bach-ma-hoang-tu) — mang ý nghĩa thành đạt, thăng tiến, \"phong thái lịch lãm\". Đây là quà thăng chức rất được chuộng.", "[Trầu bà đế vương xanh](/san-pham/trau-ba-de-vuong-xanh) — dáng lá uy nghi, tượng trưng quyền lực, thịnh vượng; hợp phòng giám đốc.", "[Ngân hậu](/san-pham/ngan-hau) — lá bạc sang trọng cho bàn làm việc."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/e/e9/Philodendron_davidsonii2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "caption": "Trầu bà lá to bóng — quà thăng chức hợp đặt phòng làm việc."}, {"type": "h2", "text": "Quà sinh nhật, quà cho bạn bè"}, {"type": "p", "text": "Tùy sở thích người nhận:"}, {"type": "list", "items": ["**Người bận rộn, hay quên tưới**: lưỡi hổ mini, ngọc bích.", "**Người thích cây lạ, sưu tầm**: [môn quan âm](/san-pham/mon-quan-am), [môn melo](/san-pham/mon-melo).", "**Người yêu hoa**: [lan ý nữ hoàng](/san-pham/lan-y-nu-hoang) (hoa trắng nở nhiều đợt), [hoa hồng](/san-pham/hoa-hong) nếu nhà có ban công nắng.", "**Người mới tập trồng cây**: lan chi, phú quý cỡ nhỏ."], "ordered": false}, {"type": "image", "file": "https://images.rawpixel.com/editor_1024/czNmcy1wcml2YXRlL3Jhd3BpeGVsX2ltYWdlcy93ZWJzaXRlX2NvbnRlbnQvbHIvZnJmbG93ZXJfZGVsaWNhdGVfd2hpdGVfZmxvd2VyLWltYWdlLWt5YmRwNXg1LmpwZw.jpg", "caption": "Hoa lan ý — quà tặng thanh lịch cho người yêu hoa."}, {"type": "h2", "text": "Bảng gợi ý nhanh theo dịp"}, {"type": "table", "rows": [["Dịp", "Cây gợi ý", "Cỡ nên chọn"], ["Khai trương", "Phú quý, vạn lộc, đế vương đỏ, ngọc bích", "30cm–1m"], ["Tân gia", "Vạn niên thanh, ngọc ngân, lưỡi hổ, lan ý", "30–60cm"], ["Thăng chức", "Bạch mã, đế vương xanh, ngân hậu", "30–70cm"], ["Sinh nhật", "Môn quan âm, lan ý nữ hoàng, lưỡi hổ mini", "20–40cm"], ["Tặng đồng nghiệp", "Lan chi, ngọc ngân, phú quý mini", "20–30cm"]]}, {"type": "h2", "text": "Mẹo để món quà cây trọn vẹn"}, {"type": "list", "items": ["**Hỏi khéo nơi đặt cây** (bàn làm việc, sảnh, phòng khách?) để chọn đúng cỡ và loại chịu được ánh sáng ở đó.", "**Chọn chậu sứ có lỗ thoát nước** hoặc giữ chậu nhựa trồng bên trong chậu trang trí — chậu kín đáy là lý do số một khiến cây quà tặng bị úng.", "**Kèm một tấm thiệp hướng dẫn chăm ngắn**: tưới mấy ngày một lần, đặt chỗ sáng hay bóng. Có thể chép phần \"Cách chăm sóc\" trên trang sản phẩm.", "**Tránh tặng cây đang yếu, đang trổ lá non quá nhiều** — cây dễ sốc khi đổi chỗ. Xem cách [chọn cây khỏe khi mua](/goc-cham-cay/cach-chon-cay-khoe-khi-mua).", "**Tặng khi đi gặp trực tiếp** hoặc giao đúng ngày — cây để trong xe nóng nhiều giờ dễ héo lá."], "ordered": true}, {"type": "note", "title": "Tặng cây cho người nuôi thú cưng", "text": "Phú quý, vạn lộc, trầu bà, lan ý, môn đều có nhựa gây ngứa khi nhai phải. Nếu người nhận nuôi chó mèo hay có bé nhỏ, hãy chọn đuôi công, lan chi hoặc dương xỉ."}, {"type": "products", "title": "Cây làm quà tại vườn", "slugs": ["phu-quy", "van-loc", "trau-ba-de-vuong-do", "bach-ma-hoang-tu", "ngoc-bich", "lan-y-nu-hoang"]}, {"type": "p", "text": "Đặt nhiều chậu quà tặng cho sự kiện, hội nghị khách hàng? [Gửi yêu cầu báo giá sỉ](/bao-gia-si) để shop chuẩn bị cây đồng đều theo số lượng."}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Aglaonema_%27Pink_Star%27.webp/960px-Aglaonema_%27Pink_Star%27.webp', 4, '[]'::jsonb, '["quà tặng", "khai trương", "tân gia", "thăng chức"]'::jsonb, 'Gợi ý cây cảnh làm quà khai trương, tân gia, sinh nhật, thăng chức: phú quý, vạn lộc, trầu bà đế vương đỏ, bạch mã, ngọc bích, lan ý — ý nghĩa và cách chọn.'),
('cay-dat-phong-ngu', 'Nên đặt cây gì trong phòng ngủ? 5 cây nhỏ gọn, ít chăm và những điều cần biết', 'Đặt cây trong phòng ngủ có tốt không, cây có "hút oxy ban đêm" không, nên chọn cây nào và đặt ở đâu? Bài này trả lời từng câu hỏi bằng thông tin thực tế, gợi ý 5 cây hợp phòng ngủ và cách đặt để không ẩm mốc, không hút muỗi.', '[{"type": "p", "text": "Phòng ngủ là nơi nhiều người muốn có một chậu cây nhỏ cho dịu mắt, nhưng cũng hay lo: cây có \"giành oxy\" ban đêm không, có làm phòng ẩm, sinh muỗi không? Bài này trả lời ngắn gọn từng thắc mắc rồi gợi ý cây phù hợp."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/FND1JADL6W.jpg", "caption": "Phòng ngủ sáng sủa với một chậu cây xanh cạnh bàn — một vài chậu nhỏ là đủ làm dịu không gian."}, {"type": "h2", "text": "Cây có \"hút hết oxy\" trong phòng ngủ ban đêm không?"}, {"type": "p", "text": "Ban đêm cây không quang hợp nên có hô hấp, tức là dùng một ít oxy và thải CO₂. Nhưng **lượng này rất nhỏ** — một vài chậu cây cảnh trong phòng ngủ dùng oxy ít hơn rất nhiều so với chính người ngủ trong phòng, hay một chú chó mèo nằm cạnh. Chừng nào phòng ngủ còn cửa, còn khe thông gió như mọi phòng bình thường, vài chậu cây không ảnh hưởng gì đến chất lượng không khí."}, {"type": "p", "text": "Ngược lại, cũng đừng kỳ vọng cây \"tạo oxy ban đêm\" hay \"lọc sạch không khí\" trong phòng ngủ. Lưỡi hổ đúng là có kiểu quang hợp đặc biệt (mở khí khổng ban đêm), nhưng lượng oxy tạo ra từ vài chậu cây là không đáng kể với một căn phòng. Lợi ích thật sự của cây trong phòng ngủ là **cảm giác thư giãn, dễ chịu khi nhìn thấy màu xanh**."}, {"type": "h2", "text": "Vậy đặt bao nhiêu cây là hợp lý?"}, {"type": "list", "items": ["Phòng ngủ 12–20m²: **1–3 chậu nhỏ và vừa** là đủ đẹp, dễ chăm.", "Tránh biến phòng ngủ thành \"vườn\" với hàng chục chậu: nhiều đất ẩm, nhiều nước tưới làm phòng ẩm hơn, dễ có nấm mốc và côn trùng nhỏ."], "ordered": false}, {"type": "h2", "text": "5 cây hợp phòng ngủ"}, {"type": "h3", "text": "Lưỡi hổ"}, {"type": "p", "text": "[Lưỡi hổ](/san-pham/luoi-ho) cỡ mini hoặc 40–50cm, đặt góc phòng, cạnh tủ. Tưới 7–10 ngày một lần nên đất gần như luôn khô — **không làm phòng ẩm, không sinh muỗi**. Đây là cây phòng ngủ dễ nhất."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/Young_snake_plant_%28Sansevieria%29_in_pot.jpg/960px-Young_snake_plant_%28Sansevieria%29_in_pot.jpg", "caption": "Lưỡi hổ con trong chậu nhỏ — hợp tủ đầu giường, ít tưới."}, {"type": "h3", "text": "Lan chi"}, {"type": "p", "text": "[Lan chi](/san-pham/lan-chi) lá sọc trắng rủ mềm, đặt trên kệ hoặc treo cạnh cửa sổ. An toàn với chó mèo, hợp phòng ngủ có thú cưng nằm cùng."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/03RGWASUK1.jpg", "caption": "Lan chi đặt trên bàn — lá sọc mềm mại, cây an toàn với chó mèo."}, {"type": "h3", "text": "Lan ý"}, {"type": "p", "text": "[Lan ý](/san-pham/lan-y) hoa trắng thanh, lá xanh đậm, chịu bóng tốt — hợp phòng ngủ có cửa sổ kéo rèm. Lưu ý lan ý có nhựa gây ngứa, đặt xa tầm với của trẻ nhỏ. Hoa lan ý có phấn; người dễ dị ứng phấn hoa nên cắt bỏ hoa khi hoa bắt đầu tàn."}, {"type": "h3", "text": "Đuôi công"}, {"type": "p", "text": "[Đuôi công xanh](/san-pham/duoi-cong-xanh) lá hoa văn dịu, cụp lá buổi tối như \"đi ngủ\" cùng chủ nhà. An toàn với chó mèo. Cần giữ ẩm đều, tránh gió máy lạnh thổi thẳng."}, {"type": "h3", "text": "Dương xỉ"}, {"type": "p", "text": "[Dương xỉ](/san-pham/duong-xi) treo giỏ cạnh cửa sổ phòng ngủ rất mát mắt. Cây cần đất luôn ẩm, nên đặt khay hứng nước bên dưới để không nhỏ nước xuống sàn."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/%E6%B3%A2%E5%A3%AB%E9%A0%93%E8%85%8E%E8%95%A8.jpg/960px-%E6%B3%A2%E5%A3%AB%E9%A0%93%E8%85%8E%E8%95%A8.jpg", "caption": "Dương xỉ lá kiếm — hợp giỏ treo cạnh cửa sổ."}, {"type": "h2", "text": "So sánh nhanh"}, {"type": "table", "rows": [["Cây", "Tưới", "Ánh sáng", "Thú cưng", "Ưu điểm phòng ngủ"], ["Lưỡi hổ", "7–10 ngày", "Chịu bóng", "Độc nhẹ", "Đất khô, không ẩm, không muỗi"], ["Lan chi", "2–3 lần/tuần", "Tán xạ", "An toàn", "Dễ chăm, mềm mại"], ["Lan ý", "2–3 lần/tuần", "Chịu bóng", "Gây ngứa", "Có hoa trắng"], ["Đuôi công", "2–3 lần/tuần", "Tán xạ nhẹ", "An toàn", "Lá đẹp, cụp tối"], ["Dương xỉ", "Mỗi ngày", "Tán xạ", "An toàn", "Mát mắt, treo được"]]}, {"type": "h2", "text": "Đặt cây trong phòng ngủ sao cho đúng"}, {"type": "list", "items": ["**Không đặt cây ngay đầu giường trên chỗ nằm** — tránh đất, nước rơi xuống gối, côn trùng nhỏ bò xuống giường.", "**Đặt gần cửa sổ** hoặc nơi có ánh sáng tán xạ; phòng ngủ kéo rèm kín cả ngày thì chọn lưỡi hổ và luân phiên mang cây ra chỗ sáng.", "**Không để nước đọng dưới đĩa lót** — nước đọng là nơi muỗi đẻ trứng. Đổ nước thừa sau khi tưới 15–20 phút.", "**Phủ mặt chậu bằng sỏi trắng** giúp đất không bị ẩm mặt, hạn chế ruồi giấm, muỗi nhỏ.", "**Tưới buổi sáng**, không tưới trước khi đi ngủ để đất kịp ráo bớt."], "ordered": true}, {"type": "note", "title": "Phòng ngủ có máy lạnh chạy suốt đêm", "text": "Không khí khô làm mép lá cây ưa ẩm (đuôi công, dương xỉ) dễ cháy. Đặt cây xa luồng gió và gom các chậu gần nhau để giữ ẩm cho nhau."}, {"type": "products", "title": "Cây phòng ngủ tại vườn", "slugs": ["luoi-ho", "lan-chi", "lan-y", "duoi-cong-xanh", "duong-xi"]}, {"type": "p", "text": "Tò mò về chuyện cây \"lọc không khí\"? Đọc bài [cây cảnh có lọc không khí thật không](/goc-cham-cay/cay-canh-loc-khong-khi-that-khong) để biết sự thật và cách làm không khí trong nhà dễ chịu hơn."}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/FND1JADL6W.jpg', 4, '[]'::jsonb, '["phòng ngủ", "cây trong nhà", "lưỡi hổ", "dễ chăm"]'::jsonb, 'Cây đặt phòng ngủ: lưỡi hổ, lan chi, lan ý, đuôi công, dương xỉ. Cây có hút oxy ban đêm không, nên đặt mấy chậu, đặt ở đâu để không ẩm mốc, có muỗi.'),
('cay-trang-tri-quan-ca-phe', 'Cây xanh cho quán cà phê: chọn cây theo từng khu, từ quầy bar đến sân vườn', 'Quán cà phê nhiều cây xanh luôn hút khách chụp ảnh và ngồi lâu hơn. Nhưng quán có máy lạnh, có nắng sân trước, có khách chạm vào cây mỗi ngày. Bài này chia quán thành từng khu và gợi ý cây bền, ít rụng lá, dễ chăm cho chủ quán bận rộn.', '[{"type": "p", "text": "Với quán cà phê, cây xanh không chỉ để trang trí mà là một phần trải nghiệm: khách thích góc chụp ảnh có cây, thích ngồi dưới tán xanh, và nhớ quán vì cảm giác \"mát mắt\". Nhưng quán là môi trường khó: sân trước nắng gắt, trong nhà máy lạnh, nhân viên thay ca nên chăm không đều, khách chạm vào cây, đặt ly lên chậu."}, {"type": "p", "text": "Chọn đúng cây cho từng khu sẽ giúp quán đẹp lâu mà không tốn công thay cây liên tục."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/VBV838R9TU.jpg", "caption": "Quán cà phê với chậu cây treo phía trên quầy ngồi — cây treo tạo mảng xanh mà không chiếm chỗ."}, {"type": "h2", "text": "Khu trong nhà có máy lạnh"}, {"type": "h3", "text": "Cây treo trên cao: dương xỉ"}, {"type": "p", "text": "[Dương xỉ](/san-pham/duong-xi) giỏ treo 25cm là \"đặc sản\" của quán cà phê: lá rủ dài, xanh mướt, tạo mảng xanh phía trên mà không chiếm diện tích. Dương xỉ cần đất luôn ẩm — với quán máy lạnh, nên tưới mỗi sáng trước giờ mở cửa và đặt cách luồng gió lạnh."}, {"type": "h3", "text": "Cây đặt sàn: trầu bà đế vương"}, {"type": "p", "text": "[Trầu bà đế vương xanh](/san-pham/trau-ba-de-vuong-xanh) hoặc [đỏ](/san-pham/trau-ba-de-vuong-do) cỡ 50–70cm hay loại 3 thân đặt ở góc, cạnh vách ngăn bàn. Lá to bóng, chịu bóng, ít rụng lá — sàn quán luôn sạch."}, {"type": "h3", "text": "Cây trên bàn, quầy: lan ý, cây nhỏ"}, {"type": "p", "text": "[Lan ý](/san-pham/lan-y) cho quầy bar, bàn dài; hoa trắng nở nhiều đợt hợp phong cách tối giản. Bàn khách nên dùng chậu thật nhỏ, vững, khó đổ (ngọc bích, sen đá nhỏ) — hoặc không đặt cây trên bàn để khách có chỗ để ly."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/VQ7MOYUFIE.jpg", "caption": "Bàn cà phê với chậu cây mọng nước nhỏ — chậu trên bàn khách nên nhỏ, nặng đáy, khó đổ."}, {"type": "h3", "text": "Kệ, tường: lan chi, đuôi công"}, {"type": "p", "text": "Kệ tường là nơi đẹp để xếp [lan chi](/san-pham/lan-chi) (lá rủ), [đuôi công](/goc-cham-cay/phan-biet-cay-duoi-cong-calathea) (lá hoa văn). Kệ cạnh cửa sổ sáng giúp cây giữ màu lá đẹp."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/JOHHVIOMIW.jpg", "caption": "Kệ tường xếp nhiều chậu cây nhỏ — kiểu trang trí \"tường xanh\" dễ làm cho quán."}, {"type": "h2", "text": "Khu sân trước, sân vườn có nắng"}, {"type": "p", "text": "Sân quán thường nắng gắt buổi chiều. Nên chọn cây ưa nắng, chịu nóng, tán gọn:"}, {"type": "list", "items": ["[Chuối rẻ quạt](/san-pham/chuoi-re-quat) — lá xòe hình quạt cực kỳ ấn tượng, là góc chụp ảnh \"đinh\" của nhiều quán sân vườn. Ưa nắng trực tiếp, tưới mỗi ngày mùa nắng. Cây lớn nhanh, cao 3–10m khi trưởng thành nên cần khoảng trống phía trên.", "[Cây sơ ri](/san-pham/cay-so-ri) — cây bụi lớn cho trái đỏ quanh năm, hoa hồng tím nhỏ; vừa có bóng mát vừa có trái — khách rất thích. Cần ít nhất 6 giờ nắng mỗi ngày.", "[Thiên điểu Thái](/san-pham/thien-dieu-thai) — dáng lá lớn kiểu nhiệt đới, hợp bồn cây cạnh lối đi.", "[Cau trắng](/san-pham/cau-trang) — trồng hàng dọc lối vào, tán gọn trên ngọn, không che bảng hiệu."], "ordered": false}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/09261jfPaddy_fields_Ravenala_irrigation_Bagong_Nayon_Baliuag_Bulacan_Road_Bridgesfvf_37.jpg/960px-09261jfPaddy_fields_Ravenala_irrigation_Bagong_Nayon_Baliuag_Bulacan_Road_Bridgesfvf_37.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Chuối rẻ quạt xòe lá hình quạt — điểm nhấn nhiệt đới cho sân quán."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Ramo_de_Acerolas%2C_Taubat%C3%A9.jpg/960px-Ramo_de_Acerolas%2C_Taubat%C3%A9.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Cây sơ ri trĩu trái đỏ — vừa cho bóng mát vừa làm khách thích thú."}, {"type": "h2", "text": "Bảng chọn cây theo khu"}, {"type": "table", "rows": [["Khu", "Cây gợi ý", "Lưu ý"], ["Treo trên cao", "Dương xỉ giỏ treo", "Tưới mỗi sáng, có khay hứng nước"], ["Góc sàn trong nhà", "Trầu bà đế vương xanh / đỏ", "Xoay chậu mỗi tuần"], ["Quầy bar", "Lan ý", "Lá rũ là cần tưới"], ["Kệ tường", "Lan chi, đuôi công", "Gần cửa sổ sáng"], ["Sân trước nắng", "Chuối rẻ quạt, sơ ri, thiên điểu", "Tưới mỗi ngày mùa khô"], ["Lối vào", "Cau trắng", "Trồng thành hàng"]]}, {"type": "h2", "text": "Mẹo chăm cây cho chủ quán"}, {"type": "list", "items": ["**Lập bảng tưới dán cạnh quầy pha chế**, giao cho ca sáng. Nhóm cây trong nhà và ngoài sân tưới khác nhau.", "**Không tưới bằng nước đá, cà phê, trà thừa** — đường và dầu làm đất chua, sinh nấm, kiến.", "**Chậu đặt sàn cần đế có bánh xe** để dễ lau sàn và luân phiên đổi chỗ sáng / tối.", "**Khách hay chạm lá**: chọn cây lá dày, cứng (trầu bà, lưỡi hổ) cho chỗ đông người qua lại; cây lá mỏng mềm (dương xỉ, đuôi công) để chỗ khuất hoặc trên cao.", "**Cắt lá vàng, lau lá mỗi tuần** — cây sạch lá là một phần \"vệ sinh\" của quán.", "**Kiểm tra sâu bệnh định kỳ**: quán có đồ ngọt dễ có kiến kéo theo [rệp sáp](/benh-cay/rep-sap), [rệp muội](/benh-cay/rep-muoi)."], "ordered": true}, {"type": "note", "title": "Quán mới mở cần nhiều cây cùng lúc", "text": "Từ vài chục chậu trở lên hoặc cần cây lớn cho sân, chủ quán có thể gửi danh sách để nhận báo giá sỉ. Shop giao cây đồng đều về kích thước, kèm hướng dẫn chăm cho nhân viên."}, {"type": "products", "title": "Cây cho quán cà phê", "slugs": ["duong-xi", "trau-ba-de-vuong-xanh", "lan-y", "chuoi-re-quat", "cay-so-ri", "thien-dieu-thai"]}, {"type": "p", "text": "Xem thêm chương trình dành cho [đối tác mua sỉ](/doi-tac) hoặc [gửi yêu cầu báo giá](/bao-gia-si)."}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/VBV838R9TU.jpg', 4, '[]'::jsonb, '["quán cà phê", "trang trí", "sân vườn", "kinh doanh"]'::jsonb, 'Chọn cây xanh trang trí quán cà phê: dương xỉ treo, trầu bà đế vương, lan ý trong nhà; chuối rẻ quạt, sơ ri, thiên điểu cho sân vườn. Mẹo chăm cho chủ quán.'),
('cay-de-cham-cho-nguoi-moi-bat-dau', 'Mới tập trồng cây nên bắt đầu từ cây gì? 6 cây "khó chết" và 7 lỗi người mới hay mắc', 'Nhiều người mua cây về vài tuần là héo rồi nghĩ mình "không hợp trồng cây". Thật ra phần lớn là do chọn cây khó và mắc vài lỗi rất phổ biến. Bài này gợi ý 6 cây dễ sống nhất và chỉ ra 7 lỗi người mới hay mắc để bạn tránh từ đầu.', '[{"type": "p", "text": "\"Em trồng cây gì cũng chết\" là câu shop nghe rất nhiều. Tin vui: gần như ai cũng trồng được cây, chỉ cần **chọn cây dễ để bắt đầu** và tránh vài lỗi cơ bản. Sau 2–3 tháng giữ được cây đầu tiên xanh tốt, bạn sẽ tự tin chuyển sang những cây \"khó tính\" hơn."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/OG7ZU1AGUC.jpg", "caption": "Một chậu cây nhỏ trên nền trắng — bắt đầu với một cây dễ, chăm thành thạo rồi mới thêm cây khác."}, {"type": "h2", "text": "6 cây \"khó chết\" cho người mới"}, {"type": "h3", "text": "1. Lưỡi hổ"}, {"type": "p", "text": "[Lưỡi hổ](/san-pham/luoi-ho) đứng đầu danh sách: chịu bóng, chịu khô, tưới 7–10 ngày một lần, hiếm khi sâu bệnh. Cách duy nhất để làm chết lưỡi hổ là **tưới quá nhiều**."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Snake_plant_%28Sansevieria_trifasciata%29_Waoleona_Buton_Island_01.jpg/960px-Snake_plant_%28Sansevieria_trifasciata%29_Waoleona_Buton_Island_01.jpg", "caption": "Lưỡi hổ sọc lá vàng — cây dễ sống nhất cho người mới."}, {"type": "h3", "text": "2. Lan chi"}, {"type": "p", "text": "[Lan chi](/san-pham/lan-chi) rễ củ trữ nước, mọc nhanh, nhìn thấy cây lớn từng tuần nên rất \"có động lực\". Cây con mọc ở đầu ngồng — cắt xuống trồng là có cây mới, bạn sẽ được tập nhân giống luôn."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Chlorophytum_comosum_in_a_pot.jpg/960px-Chlorophytum_comosum_in_a_pot.jpg", "caption": "Lan chi trong chậu — rễ củ chịu khô, mọc nhanh."}, {"type": "h3", "text": "3. Phú quý và 4. Vạn lộc"}, {"type": "p", "text": "[Phú quý](/san-pham/phu-quy) và [vạn lộc](/san-pham/van-loc) chịu bóng, tưới khi đất mặt khô, lá dày ít bị hỏng. Màu đỏ hồng đẹp, nhìn có \"thành quả\" ngay."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/9714Philippines_Elephant_ear_Aglaonema_16.jpg/960px-9714Philippines_Elephant_ear_Aglaonema_16.jpg", "caption": "Aglaonema trồng chậu nhỏ — nhóm phú quý, vạn lộc dễ chăm, chịu bóng."}, {"type": "h3", "text": "5. Bạch mã"}, {"type": "p", "text": "[Bạch mã](/san-pham/bach-ma-hoang-tu) cùng nhóm Aglaonema, dáng cao thanh, chịu bóng râm tốt — hợp người muốn cây cỡ lớn hơn một chút cho góc phòng."}, {"type": "h3", "text": "6. Ngọc bích (nếu nhà có nắng)"}, {"type": "p", "text": "[Ngọc bích](/san-pham/ngoc-bich) cực dễ nếu đặt đúng chỗ có nắng sáng 4–6 giờ: tưới mỗi tuần một lần là đủ. Không có nắng thì đừng chọn ngọc bích."}, {"type": "h2", "text": "7 lỗi người mới hay mắc"}, {"type": "h3", "text": "Lỗi 1: Tưới quá nhiều"}, {"type": "p", "text": "Đây là lỗi số một, giết nhiều cây hơn cả quên tưới. Rễ cây cần không khí; đất ướt liên tục làm rễ ngạt, [thối rễ](/benh-cay/thoi-re). **Quy tắc**: cắm ngón tay xuống đất 2–3cm, còn ẩm thì chưa tưới."}, {"type": "h3", "text": "Lỗi 2: Chậu không có lỗ thoát nước"}, {"type": "p", "text": "Chậu sứ đẹp kín đáy khiến nước đọng ở đáy, rễ thối dần mà bạn không thấy. Luôn trồng trong chậu có lỗ, đặt vào chậu trang trí nếu muốn."}, {"type": "h3", "text": "Lỗi 3: Đặt sai ánh sáng"}, {"type": "p", "text": "Cây ưa nắng để trong góc tối, hoặc cây chịu bóng phơi nắng trưa. Đọc mục **Ánh sáng** trên trang sản phẩm trước khi chọn chỗ đặt."}, {"type": "h3", "text": "Lỗi 4: Thay chậu ngay khi vừa mua"}, {"type": "p", "text": "Cây vừa về nhà đã chịu sốc vì đổi chỗ. Thay chậu luôn là thêm một cú sốc. **Hãy để cây quen chỗ 2–3 tuần** rồi mới thay chậu (nếu thật sự cần)."}, {"type": "h3", "text": "Lỗi 5: Bón phân để \"cứu\" cây yếu"}, {"type": "p", "text": "Cây đang vàng, héo mà bón phân thì như ép người ốm ăn nhiều — dễ [cháy rễ](/benh-cay/chay-re-do-phan). Tìm nguyên nhân (nước, ánh sáng, sâu bệnh) trước, cây khỏe lại mới bón."}, {"type": "h3", "text": "Lỗi 6: Đổi chỗ cây liên tục"}, {"type": "p", "text": "Cây cần thời gian thích nghi với ánh sáng mới. Dời chỗ mỗi vài ngày khiến cây rụng lá, vàng lá. Chọn một chỗ hợp rồi để yên."}, {"type": "h3", "text": "Lỗi 7: Mua quá nhiều cây cùng lúc"}, {"type": "p", "text": "Mười chậu mười kiểu tưới khác nhau, người mới rất dễ rối. **Bắt đầu với 1–3 cây cùng nhóm chăm** (ví dụ: lưỡi hổ + phú quý + vạn lộc), giữ được 2–3 tháng rồi hãy thêm."}, {"type": "image", "file": "https://images.rawpixel.com/editor_1024/cHJpdmF0ZS9zdGF0aWMvaW1hZ2Uvd2Vic2l0ZS8yMDIyLTA0L2xyL2Zyd2F0ZXJpbmdfY2FuX2dhcmRlbl9ib3hfMC1pbWFnZS1reWJjYjR2dS5qcGc.jpg", "caption": "Bình tưới đặt cạnh chậu cây — tưới đúng lúc quan trọng hơn tưới nhiều."}, {"type": "h2", "text": "Lịch chăm mẫu cho tháng đầu tiên"}, {"type": "table", "rows": [["Tuần", "Việc cần làm"], ["Tuần 1", "Đặt cây đúng chỗ ánh sáng, không thay chậu, không bón phân. Kiểm tra đất 2 ngày một lần."], ["Tuần 2", "Tưới khi đất khô theo đúng loại cây. Quan sát lá: lá mới có ra không, lá cũ có vàng không."], ["Tuần 3", "Lau bụi lá bằng khăn ẩm. Xoay chậu 1/4 vòng."], ["Tuần 4", "Nếu cây khỏe, ra lá mới: có thể bón phân tan chậm liều nhẹ. Ghi lại lịch tưới đã hợp."]]}, {"type": "note", "title": "Mẹo nhớ lịch tưới", "text": "Đặt nhắc lịch trên điện thoại, hoặc dùng mục **Vườn của tôi** và **Lịch chăm cây** trong tài khoản trên web — cây mua tại shop sẽ tự có lịch nhắc tưới, bón phân."}, {"type": "products", "title": "Cây cho người mới bắt đầu", "slugs": ["luoi-ho", "lan-chi", "phu-quy", "van-loc", "bach-ma-hoang-tu", "ngoc-bich"]}, {"type": "p", "text": "Khi đã tự tin, thử sức với nhóm lá đẹp hơn như [đuôi công](/goc-cham-cay/phan-biet-cay-duoi-cong-calathea) hay [môn quan âm, môn melo](/goc-cham-cay/mon-quan-am-va-mon-melo)."}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/OG7ZU1AGUC.jpg', 4, '[]'::jsonb, '["người mới", "dễ chăm", "khó chết", "hướng dẫn"]'::jsonb, 'Cây dễ trồng cho người mới bắt đầu: lưỡi hổ, lan chi, phú quý, vạn lộc, bạch mã, ngọc bích. 7 lỗi người mới hay mắc khi chăm cây và cách tránh.'),
('cach-chon-cay-khoe-khi-mua', 'Cách chọn cây khỏe khi mua: kiểm tra lá, thân, rễ và sâu bệnh trong 5 phút', 'Cây mua về khỏe hay yếu quyết định gần một nửa chuyện chăm dễ hay khó. Bài này hướng dẫn kiểm tra cây trong 5 phút khi mua tại vườn hoặc khi nhận cây giao tận nơi: nhìn lá, xem thân gốc, kiểm tra rễ, soi sâu bệnh, và việc cần làm trong tuần đầu.', '[{"type": "p", "text": "Một cây khỏe từ lúc mua sẽ chịu được những sai sót nhỏ khi chăm, nhanh quen chỗ mới và lớn đều. Một cây yếu, có sẵn sâu bệnh thì dù chăm kỹ cũng dễ \"đi\" sau vài tuần. Dưới đây là cách kiểm tra cây mà nhân viên vườn vẫn làm khi chọn cây giao cho khách — bạn có thể tự làm trong khoảng 5 phút."}, {"type": "image", "file": "https://images.rawpixel.com/editor_1024/cHJpdmF0ZS9sci9pbWFnZXMvd2Vic2l0ZS8yMDIyLTExL2ZsNTE1MTI1NzEwMDAtaW1hZ2UuanBn.jpg", "caption": "Vườn ươm với nhiều khay cây con xếp hàng — chọn cây đồng đều, lá xanh, không có cây bệnh bên cạnh."}, {"type": "h2", "text": "Bước 1: Nhìn tổng thể cây"}, {"type": "p", "text": "Đứng cách cây khoảng 1m và nhìn:"}, {"type": "list", "items": ["**Dáng cân đối**, lá phân bố đều quanh thân, không nghiêng hẳn một phía.", "**Màu lá đúng với giống**: lá xanh thì xanh đậm, bóng; lá đỏ thì đỏ tươi. Lá nhạt, vàng loang hàng loạt là dấu hiệu cây thiếu dinh dưỡng hoặc úng.", "**Có lá non hoặc chồi mới** ở ngọn — dấu hiệu cây đang sinh trưởng tốt.", "**Không quá vươn dài, lá thưa**: cây bị để thiếu sáng lâu, về nhà khó đẹp lại."], "ordered": false}, {"type": "h2", "text": "Bước 2: Kiểm tra lá — cả mặt trên và mặt dưới"}, {"type": "p", "text": "Lật 3–4 lá ở các tầng khác nhau, nhất là **mặt dưới lá và nách lá** — nơi sâu bệnh hay ẩn:"}, {"type": "table", "rows": [["Bạn thấy", "Có thể là", "Mức độ"], ["Đốm trắng như bông, dính ở nách lá", "[Rệp sáp](/benh-cay/rep-sap)", "Nên tránh, dễ lây cây khác"], ["Chấm li ti, tơ mịn, lá mờ màu", "[Nhện đỏ](/benh-cay/nhen-do)", "Nên tránh"], ["Đốm nâu có viền vàng", "[Đốm lá do nấm](/benh-cay/dom-la-nam)", "Tránh nếu nhiều lá"], ["Lớp bụi đen như bồ hóng", "[Muội đen](/benh-cay/muoi-den), thường kèm rệp", "Nên tránh"], ["Mép lá khô nâu nhẹ ở 1–2 lá già", "Cháy mép do khô, gió", "Chấp nhận được"], ["Lá già dưới cùng vàng 1–2 lá", "Lá già tự nhiên", "Bình thường"]]}, {"type": "h2", "text": "Bước 3: Xem thân và gốc"}, {"type": "list", "items": ["**Ấn nhẹ phần gốc sát đất**: phải chắc, không mềm nhũn. Gốc mềm, thâm đen, có mùi hôi là dấu hiệu thối gốc.", "**Lay nhẹ thân**: cây bám chắc trong chậu là rễ khỏe. Cây lỏng lẻo, nhấc nhẹ đã muốn bật lên có thể mới được \"cấy\" vào chậu hoặc rễ đã thối.", "**Thân không có vết nứt, vết sâu đục** (lỗ nhỏ có mùn gỗ)."], "ordered": false}, {"type": "h2", "text": "Bước 4: Kiểm tra rễ (nếu được phép)"}, {"type": "p", "text": "Với cây chậu nhựa, có thể xin nghiêng chậu, nhìn qua lỗ thoát nước dưới đáy:"}, {"type": "list", "items": ["**Rễ trắng hoặc vàng nhạt, chắc**: rễ khỏe.", "**Rễ nâu đen, mềm, có mùi hôi**: rễ thối do úng — không nên mua.", "**Rễ mọc dày đặc ra ngoài lỗ đáy**: cây đã chật chậu, vẫn khỏe nhưng cần thay chậu sau khi về nhà 2–3 tuần."], "ordered": false}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/WV6Q25F8ZJ.jpg", "caption": "Đất trồng tơi xốp, thoát nước tốt — rễ khỏe phát triển trong đất thoáng."}, {"type": "h2", "text": "Bước 5: Xem đất trong chậu"}, {"type": "list", "items": ["Đất **ẩm vừa**, không sũng nước, không nứt nẻ khô cứng.", "Không có nấm mốc trắng phủ mặt chậu, không có nhiều ruồi nhỏ bay lên khi chạm vào.", "Mặt đất có rêu xanh nhẹ là bình thường ở cây vườn ươm."], "ordered": false}, {"type": "h2", "text": "Khi nhận cây giao tận nơi"}, {"type": "p", "text": "Cây đi đường xa có thể bị **rũ lá, gãy 1–2 lá, rụng vài lá** vì nằm trong thùng thiếu sáng — đó là hiện tượng bình thường, cây sẽ hồi lại sau vài ngày. Khi nhận cây:"}, {"type": "list", "items": ["**Mở thùng ngay**, đưa cây ra chỗ thoáng có ánh sáng tán xạ (không phơi nắng gắt ngay).", "**Chụp ảnh cây** lúc vừa mở hộp — cần khi yêu cầu bảo hành.", "**Kiểm tra đất**: khô thì tưới nhẹ, ướt thì để ráo.", "**Kiểm tra gốc và mặt dưới lá** như các bước trên.", "**Không thay chậu, không bón phân** trong 2–3 tuần đầu."], "ordered": true}, {"type": "note", "title": "Bảo hành cây sống", "text": "Cây sống mua tại shop được bảo hành theo [chính sách bảo hành cây](/chinh-sach/bao-hanh-cay). Nếu cây có dấu hiệu bất thường trong thời gian bảo hành, chụp ảnh và gửi yêu cầu trong mục Bảo hành cây ở tài khoản, hoặc nhắn shop qua Zalo."}, {"type": "h2", "text": "Tuần đầu tiên ở nhà mới"}, {"type": "list", "items": ["**Cách ly cây mới 1–2 tuần**, đặt xa các cây khác trong nhà nếu được — phòng trường hợp có sâu bệnh chưa phát hiện lây sang.", "**Quan sát lá mỗi ngày** trong tuần đầu: lá rũ nhẹ rồi tươi lại là cây đang quen chỗ.", "**Một vài lá vàng rụng trong 1–2 tuần đầu** là phản ứng tự nhiên khi đổi môi trường ([sốc môi trường](/benh-cay/rung-la-soc-moi-truong)), không cần lo nếu lá non vẫn tốt."], "ordered": false}, {"type": "image", "file": "https://images.rawpixel.com/editor_1024/cHJpdmF0ZS9sci9pbWFnZXMvd2Vic2l0ZS8yMDIyLTExL2ZsNTE1MTA4MzQwNDItaW1hZ2UuanBn.jpg", "caption": "Khay cây con ở vườn ươm — cây khỏe có lá xanh đều, thân chắc."}, {"type": "products", "title": "Cây dễ sống cho lần mua đầu", "slugs": ["luoi-ho", "phu-quy", "van-loc", "lan-chi", "bach-ma-hoang-tu", "trau-ba-de-vuong-xanh"]}, {"type": "p", "text": "Muốn xem cây tận mắt trước khi mua? Ghé [vườn tại Sa Đéc](/he-thong-cua-hang) — shop khám lá bệnh miễn phí, bạn có thể mang lá cây đang bệnh ở nhà đến hỏi."}]'::jsonb, 'https://images.rawpixel.com/editor_1024/cHJpdmF0ZS9sci9pbWFnZXMvd2Vic2l0ZS8yMDIyLTExL2ZsNTE1MTI1NzEwMDAtaW1hZ2UuanBn.jpg', 4, '["rep-sap", "nhen-do", "thoi-re", "dom-la-nam"]'::jsonb, '["chọn cây khỏe", "mua cây", "kiểm tra cây", "sâu bệnh"]'::jsonb, 'Cách chọn cây cảnh khỏe khi mua: kiểm tra lá, thân, gốc, rễ, mặt dưới lá tìm rệp sáp, nhện đỏ; việc cần làm tuần đầu khi nhận cây giao tận nơi.'),
('chon-chau-va-co-cay-ma-chau-c', 'Chọn chậu và cỡ cây: hiểu mã chậu C6, C7, C9, C10 của nhà vườn và cách chọn chậu cho đúng', 'Đọc tên sản phẩm thấy "chậu C9", "chậu C10" mà không biết to cỡ nào? Bài này giải thích mã chậu nhựa nhà vườn Sa Đéc dùng, cỡ cây tương ứng, cách chọn cỡ cây theo vị trí đặt và khi nào nên thay chậu lớn hơn.', '[{"type": "p", "text": "Khi xem cây trên web, bạn sẽ gặp hai kiểu ghi quy cách: theo **chiều cao cây** (\"Cao 30–50cm\") hoặc theo **mã chậu** (\"Chậu C9 (miệng 23cm)\"). Kiểu ghi theo mã chậu là cách các nhà vườn ở Làng hoa Sa Đéc vẫn dùng khi bán sỉ, vì cây cùng một cỡ chậu thường có độ lớn tương đương nhau."}, {"type": "p", "text": "Bài này giúp bạn hình dung các mã chậu và chọn cỡ cây cho đúng chỗ đặt."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/WV6Q25F8ZJ.jpg", "caption": "Đất trồng và xẻng nhỏ — chậu và đất phù hợp quyết định cây có khỏe lâu dài hay không."}, {"type": "h2", "text": "Mã chậu C là gì?"}, {"type": "p", "text": "Chậu C là loại chậu nhựa đen nhà vườn dùng để ươm và bán cây. Số sau chữ C càng lớn thì chậu càng to. Kích thước tham khảo (miệng × cao × đáy) như sau:"}, {"type": "table", "rows": [["Mã chậu", "Đường kính miệng", "Chiều cao chậu", "Đường kính đáy"], ["C6", "12cm", "10cm", "9cm"], ["C7", "15cm", "13cm", "12cm"], ["C8", "18cm", "14cm", "14cm"], ["C9", "23cm", "18cm", "17cm"], ["C10", "25cm", "20cm", "20cm"]]}, {"type": "p", "text": "Đây là số đo các chậu nhà vườn thường dùng; từng lô chậu có thể chênh lệch một chút. Chiều cao cây trong mỗi cỡ chậu khác nhau tùy loại cây — cây lá to như trầu bà đế vương trong chậu C9 sẽ trông lớn hơn hẳn lưỡi hổ cùng chậu."}, {"type": "h2", "text": "Cỡ chậu nào hợp chỗ nào?"}, {"type": "table", "rows": [["Cỡ", "Hợp đặt", "Ví dụ cây"], ["C6, C7 (miệng 12–15cm)", "Bàn làm việc, kệ nhỏ, cửa sổ", "[Trầu bà đế vương đỏ chậu C7](/san-pham/trau-ba-de-vuong-do), cây để bàn"], ["C8, C9 (miệng 18–23cm)", "Kệ tivi, bàn phụ, góc nhỏ, quầy", "[Giữ tiền chậu C9](/san-pham/giu-tien), [Trầu bà Thanh Xuân C9](/san-pham/thanh-xuan), [đế vương nâu C9](/san-pham/trau-ba-de-vuong-nau)"], ["C10 (miệng 25cm)", "Đặt sàn cạnh sofa, góc phòng, sảnh nhỏ", "[Lưỡi hổ chậu C10](/san-pham/luoi-ho)"], ["C11 trở lên", "Sàn phòng khách, sảnh văn phòng", "[Thanh lam chậu C11](/san-pham/thanh-lam)"]]}, {"type": "h2", "text": "Chọn cỡ cây theo vị trí: 3 nguyên tắc"}, {"type": "list", "items": ["**Cây để bàn không quá 1/3 chiều rộng bàn** và không che màn hình. Bàn làm việc thông thường hợp cây cao 20–40cm, chậu C6–C7.", "**Cây đặt sàn cao bằng 1/2 đến 2/3 chiều cao trần** mới thấy \"đầy\" góc phòng. Phòng trần 3m thì cây 1,2–1,8m; muốn cây nhỏ hơn thì kê trên đôn, kệ.", "**Chừa khoảng trống cho cây lớn**: cây lá xòe (trầu bà đế vương, dạ lan thanh) cần khoảng trống ngang ít nhất bằng tán hiện tại cộng thêm 20–30cm."], "ordered": true}, {"type": "h2", "text": "Chậu trang trí: chọn sao cho cây không úng"}, {"type": "p", "text": "Nhiều người mua cây về và đặt cả chậu nhựa vào chậu sứ, chậu xi măng đẹp. Cách này rất tốt — miễn là:"}, {"type": "list", "items": ["**Chậu trang trí lớn hơn chậu nhựa 2–5cm** để nhấc ra tưới, đổ nước thừa dễ dàng.", "**Lót sỏi dưới đáy chậu trang trí** để chậu nhựa không ngâm trong nước đọng.", "**Đổ nước thừa** 15–20 phút sau khi tưới nếu chậu trang trí không có lỗ."], "ordered": false}, {"type": "p", "text": "Nếu trồng thẳng vào chậu trang trí, chậu **bắt buộc có lỗ thoát nước**, lót lớp sỏi hoặc xỉ than ở đáy rồi mới cho đất."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/4M8QRWO0YA.jpg", "caption": "Cây trồng trong chậu đất nung — chậu đất nung thoáng khí, đất khô nhanh hơn chậu nhựa."}, {"type": "h2", "text": "Chậu nhựa, đất nung, sứ hay xi măng?"}, {"type": "table", "rows": [["Loại chậu", "Ưu điểm", "Nhược điểm", "Hợp cây"], ["Nhựa", "Nhẹ, rẻ, giữ ẩm lâu", "Đen dễ hấp nóng ngoài nắng", "Cây ưa ẩm, trong nhà"], ["Đất nung", "Thoáng khí, đất khô nhanh, rễ ít úng", "Nặng, dễ vỡ, đất khô nhanh", "Cây mọng nước, lưỡi hổ, ngọc bích"], ["Sứ tráng men", "Đẹp, sang, dễ lau", "Thường không có lỗ, nặng", "Cây trong nhà, làm vỏ ngoài"], ["Xi măng, composite", "Bền, hợp cây lớn ngoài trời", "Rất nặng", "Cây sân vườn, cây công trình"]]}, {"type": "h2", "text": "Khi nào cần thay chậu lớn hơn?"}, {"type": "list", "items": ["Rễ **mọc ra ngoài lỗ đáy** hoặc trồi lên mặt đất.", "Tưới xong **nước chảy ngay ra đáy**, đất khô rất nhanh (đất đã bị rễ chiếm hết).", "Cây **ngừng ra lá mới** dù đủ sáng, đủ nước, đúng mùa sinh trưởng."], "ordered": false}, {"type": "p", "text": "Cách thay: chọn chậu **lớn hơn 1 cỡ** (miệng rộng hơn 3–5cm). Chậu quá to so với rễ giữ nhiều nước thừa, dễ úng. Thay chậu vào đầu mùa mưa (tháng 5–7) là lúc cây hồi phục nhanh nhất; tránh thay khi cây đang ra hoa hoặc vừa mua về."}, {"type": "image", "file": "https://images.rawpixel.com/editor_1024/czNmcy1wcml2YXRlL3Jhd3BpeGVsX2ltYWdlcy93ZWJzaXRlX2NvbnRlbnQvbHIvcHg1NjA4NTUtaW1hZ2Uta3d5cDVwbDEuanBn.jpg", "caption": "Cây con mới nảy trong đất — thay chậu đúng cỡ giúp rễ phát triển khỏe."}, {"type": "note", "title": "Không thay chậu cho cây vừa mua", "text": "Cây vừa về nhà cần 2–3 tuần làm quen với ánh sáng, nhiệt độ mới. Thay chậu ngay là thêm một cú sốc cho rễ. Đợi cây ra lá mới rồi hãy thay."}, {"type": "products", "title": "Cây theo mã chậu tại vườn", "slugs": ["luoi-ho", "giu-tien", "thanh-xuan", "trau-ba-de-vuong-nau", "trau-ba-de-vuong-do", "thanh-lam"]}, {"type": "p", "text": "Chưa biết chọn cỡ nào cho không gian nhà mình? Chụp ảnh chỗ định đặt cây, nhắn shop qua Zalo kèm kích thước để được tư vấn cỡ cây phù hợp."}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/WV6Q25F8ZJ.jpg', 4, '[]'::jsonb, '["chậu cây", "kích thước", "thay chậu", "hướng dẫn mua"]'::jsonb, 'Mã chậu C6, C7, C8, C9, C10 nhà vườn là gì: kích thước miệng, chiều cao chậu, cỡ cây phù hợp. Cách chọn cỡ cây theo vị trí và thời điểm thay chậu.'),
('cay-san-vuon-nha-pho-mien-tay', 'Cây sân vườn cho nhà phố, nhà vườn miền Tây: vừa đẹp, vừa có bóng mát, có cả trái ăn', 'Khí hậu miền Tây nắng nóng, mùa mưa dài, đất phù sa — rất hợp trồng cây sân vườn, nhưng cũng dễ úng gốc mùa nước. Bài này gợi ý cây cho từng phần sân: cây bóng mát, cây điểm nhấn, cây cho trái, cây hoa, kèm cách trồng tránh úng mùa mưa.', '[{"type": "p", "text": "Miền Tây có lợi thế lớn cho sân vườn: nắng nhiều, ấm quanh năm, đất phù sa màu mỡ. Thách thức là **mùa mưa kéo dài và nước lên**, sân thấp dễ ngập, gốc cây úng; còn mùa khô (tháng 12 đến tháng 4) nắng gắt, đất nứt. Chọn cây và cách trồng hợp với hai mùa này thì sân vườn sẽ xanh quanh năm."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Ravenala_madagascariensis_-_Sankyo_Garden_-_DSC01186.JPG/960px-Ravenala_madagascariensis_-_Sankyo_Garden_-_DSC01186.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Chuối rẻ quạt trong một khu vườn nhiệt đới — lá to xòe tạo điểm nhấn cho sân."}, {"type": "h2", "text": "Chia sân thành từng tầng cây"}, {"type": "p", "text": "Một sân vườn đẹp thường có 3 tầng, từ cao xuống thấp:"}, {"type": "list", "items": ["**Tầng cao — cây bóng mát, cây điểm nhấn**: che nắng cho nhà, tạo khung cho cả khu vườn.", "**Tầng giữa — cây bụi, cây cho trái**: cao 1–3m, che tầm mắt từ đường vào, có trái, có hoa.", "**Tầng thấp — hoa, cây viền**: màu sắc ở tầm mắt, viền lối đi."], "ordered": true}, {"type": "h2", "text": "Tầng cao: bóng mát và điểm nhấn"}, {"type": "list", "items": ["[Bàng Đài Loan](/san-pham/bang-dai-loan) — tán tầng gọn, lá nhỏ, hợp sân nhà phố mặt tiền, che nắng mà không chiếm quá nhiều chỗ.", "[Chuối rẻ quạt](/san-pham/chuoi-re-quat) — lá xòe hình quạt cực ấn tượng, điểm nhấn sân vườn, resort. Lưu ý cây cao 3–10m khi trưởng thành, cần khoảng trống phía trên.", "[Cau trắng](/san-pham/cau-trang) — trồng hàng dọc lối vào, hàng rào; tán gọn trên ngọn không che nắng nhiều."], "ordered": false}, {"type": "p", "text": "Sân rộng muốn cây bóng mát lớn hơn có thể xem các cây công trình như bằng lăng, kèn hồng trong bài [chọn cây công trình](/goc-cham-cay/chon-cay-cong-trinh-duong-pho-san-truong)."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Ravenala_madagascariensis_-_Mounts_Botanical_Garden_-_Palm_Beach_County%2C_Florida_-_DSC03689.jpg/960px-Ravenala_madagascariensis_-_Mounts_Botanical_Garden_-_Palm_Beach_County%2C_Florida_-_DSC03689.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Hàng chuối rẻ quạt trưởng thành — thân cao, tán lá xòe phía trên."}, {"type": "h2", "text": "Tầng giữa: cây cho trái, cây bụi"}, {"type": "h3", "text": "Sơ ri"}, {"type": "p", "text": "[Cây sơ ri](/san-pham/cay-so-ri) là cây quen thuộc của miền Tây (vùng Gò Công nổi tiếng sơ ri). Cây bụi lớn, ra hoa hồng tím nhỏ và **trái đỏ quanh năm**, chua ngọt, nhiều vitamin C. Ưa nắng ít nhất 6 giờ mỗi ngày, tưới đẫm mỗi ngày mùa khô, không để úng gốc mùa mưa. Vườn có bộ cây sơ ri lớn cao khoảng 3m kèm chậu, hợp khu nghỉ dưỡng, quán cà phê sân vườn."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Malpighia_emarginata_in_Margarita_Island.jpg/960px-Malpighia_emarginata_in_Margarita_Island.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Sơ ri ra trái đỏ — cây ăn trái quen thuộc ở miền Tây."}, {"type": "h3", "text": "Tắc cẩm thạch Thái"}, {"type": "p", "text": "[Tắc cẩm thạch Thái](/san-pham/tac-cam-thach-thai) lá đốm trắng xanh, trái quanh năm chín vàng — vừa làm cảnh, vừa lấy trái pha nước, chưng Tết. Trồng chậu ở hiên hoặc trồng đất đều được."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Limau_Kesturi_3.jpg/960px-Limau_Kesturi_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Bụi tắc trồng đất — cây ưa nắng, cho trái quanh năm."}, {"type": "h3", "text": "Các cây bụi khác"}, {"type": "p", "text": "Vườn còn có [Sơn tùng](/san-pham/son-tung), [Đuôi chồn cúp](/san-pham/duoi-chon-cup), [Hồng phụng](/san-pham/hong-phung), [Chanh nho](/san-pham/chanh-nho), [Thiên điểu Thái](/san-pham/thien-dieu-thai) — các giống nhà vườn trồng cho sân vườn. Nhắn shop để được gửi ảnh cây thật và tư vấn vị trí trồng."}, {"type": "h2", "text": "Tầng thấp: hoa và viền lối đi"}, {"type": "list", "items": ["[Hoa hồng](/san-pham/hoa-hong) — cần nắng 6 giờ, tưới gốc buổi sáng; bồn hồng trước nhà luôn được chú ý.", "[Mai địa thảo](/san-pham/mai-dia-thao) — hoa nhiều màu nở liên tục, hợp bồn hoa, viền lối đi chỗ nắng nhẹ buổi sáng.", "[Tulip Thái](/san-pham/tulip-thai) — hoa hồng tím mùa mưa, trồng bồn hoặc chậu.", "[Lài tây](/san-pham/lai-tay) — cây bụi thấp có hoa, giá mềm, trồng viền số lượng nhiều."], "ordered": false}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/GOCZA%C5%81KOWICE_ZDR%C3%93J%2C_AB._110.JPG/960px-GOCZA%C5%81KOWICE_ZDR%C3%93J%2C_AB._110.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Hoa hồng trồng chậu ở vườn ươm — hoa nhiều màu cho tầng thấp của sân."}, {"type": "h2", "text": "Bảng chọn nhanh theo nhu cầu"}, {"type": "table", "rows": [["Muốn có", "Cây gợi ý", "Nắng cần"], ["Bóng mát gọn cho nhà phố", "Bàng Đài Loan", "Nắng toàn phần"], ["Điểm nhấn chụp ảnh", "Chuối rẻ quạt, thiên điểu", "Nắng trực tiếp"], ["Trái ăn được", "Sơ ri, tắc cẩm thạch", "Ít nhất 6 giờ"], ["Hàng rào, lối vào", "Cau trắng", "Nắng toàn phần / một phần"], ["Hoa màu sắc", "Hoa hồng, mai địa thảo, tulip Thái", "Từ nắng nhẹ đến 6 giờ"]]}, {"type": "h2", "text": "Trồng cây sân vườn tránh úng mùa mưa"}, {"type": "list", "items": ["**Đắp mô cao 20–40cm** cho chỗ trồng nếu sân thấp, hay đọng nước. Cây sơ ri, tắc, hoa hồng rất sợ ngập gốc.", "**Đào hố rộng gấp 2 bầu cây**, trộn đất với phân hữu cơ hoai, trấu, xơ dừa cho tơi, thoát nước.", "**Làm rãnh thoát nước** quanh bồn cây trước mùa mưa (tháng 4–5).", "**Không vun đất lấp kín cổ rễ** — giữ mặt bầu cây ngang hoặc hơi cao hơn mặt đất xung quanh.", "**Phủ gốc bằng rơm, xơ dừa** mùa khô để giữ ẩm; mùa mưa kéo lớp phủ ra xa gốc cho thoáng.", "**Bón phân đầu mùa mưa và sau mùa thu hoạch** cho cây ăn trái; mùa mưa dầm không bón đạm nhiều — cây dễ sâu bệnh, [thối rễ](/benh-cay/thoi-re)."], "ordered": true}, {"type": "note", "title": "Mùa nước lên", "text": "Cây trồng chậu lớn (sơ ri, tắc, hoa hồng) nên kê lên đôn cao trước khi nước lên. Cây bị ngập gốc quá 2–3 ngày thì sau khi rút nước cần tỉa bớt lá, xới nhẹ mặt đất cho thoáng và theo dõi [héo, thối gốc](/benh-cay/thoi-goc-nam-hach)."}, {"type": "products", "title": "Cây sân vườn tại vườn", "slugs": ["chuoi-re-quat", "cay-so-ri", "tac-cam-thach-thai", "hoa-hong", "cau-trang", "bang-dai-loan"]}, {"type": "p", "text": "Cần cây số lượng nhiều cho sân vườn biệt thự, resort hoặc công trình? [Gửi yêu cầu báo giá sỉ](/bao-gia-si) để được tư vấn chọn cây theo mặt bằng."}]'::jsonb, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Ravenala_madagascariensis_-_Sankyo_Garden_-_DSC01186.JPG/960px-Ravenala_madagascariensis_-_Sankyo_Garden_-_DSC01186.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 5, '[]'::jsonb, '["sân vườn", "nhà phố", "miền Tây", "cây ăn trái"]'::jsonb, 'Cây sân vườn nhà phố miền Tây: chuối rẻ quạt, sơ ri, tắc cẩm thạch, hoa hồng, cau trắng, bàng Đài Loan, thiên điểu. Cách bố trí và trồng tránh úng mùa mưa.'),
('cay-canh-loc-khong-khi-that-khong', 'Cây cảnh có lọc không khí thật không? Sự thật về nghiên cứu NASA và điều cây thật sự làm được', '"Cây lọc không khí theo NASA" là câu quảng cáo rất quen. Nhưng một vài chậu cây có thật sự làm sạch không khí trong nhà? Bài này giải thích nghiên cứu gốc, các đánh giá sau đó, và những lợi ích có thật của cây cảnh để bạn chọn cây với kỳ vọng đúng.', '[{"type": "p", "text": "Gần như cửa hàng cây nào cũng có bảng \"Top cây lọc không khí theo NASA\": lưỡi hổ, lan ý, lan chi, trầu bà, dương xỉ… Shop cũng bán những cây này và chúng đều là cây đẹp, dễ chăm. Nhưng nói \"đặt vài chậu là lọc sạch không khí trong nhà\" thì chưa đúng. Bài này giải thích vì sao, để bạn chọn cây với kỳ vọng thực tế."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/KLXLJSBKJI.jpg", "caption": "Lan chi đặt bên cửa sổ — một trong những cây thường có tên trong danh sách \"lọc không khí\"."}, {"type": "h2", "text": "Nghiên cứu của NASA năm 1989 nói gì?"}, {"type": "p", "text": "Năm 1989, NASA cùng Hiệp hội các nhà thầu cảnh quan Hoa Kỳ công bố nghiên cứu \"Interior Landscape Plants for Indoor Air Pollution Abatement\" (Cây cảnh nội thất giúp giảm ô nhiễm không khí trong nhà). Các nhà khoa học đặt từng chậu cây vào **buồng kín nhỏ**, bơm vào các chất như benzen, formaldehyde, trichloroethylene, rồi đo lượng chất đó giảm đi sau 24 giờ."}, {"type": "p", "text": "Kết quả: nhiều loại cây (cùng với vi sinh vật trong đất) làm **giảm đáng kể** lượng chất ô nhiễm trong buồng kín. Từ đó ra đời danh sách \"cây lọc không khí\" nổi tiếng, trong đó có lưỡi hổ, lan ý, lan chi, trầu bà, dương xỉ, vạn niên thanh…"}, {"type": "h2", "text": "Vậy sao lại nói \"chưa đúng\"?"}, {"type": "p", "text": "Vấn đề nằm ở chỗ **buồng kín thí nghiệm rất khác căn phòng thật**:"}, {"type": "list", "items": ["Buồng thí nghiệm chỉ khoảng **0,5–1m³**, kín hoàn toàn. Phòng khách nhà bạn có thể 50–100m³, và không khí liên tục được thay qua cửa, khe hở, máy lạnh.", "Năm 2019, hai nhà nghiên cứu Bryan Cummings và Michael Waring (Đại học Drexel, Mỹ) tổng hợp lại hàng chục nghiên cứu theo kiểu buồng kín và tính toán ra điều kiện nhà thật. Kết luận của họ: để cây đạt hiệu quả lọc bằng việc **thông gió tự nhiên của một căn nhà bình thường**, cần khoảng **10 đến 1.000 cây trên mỗi mét vuông sàn** — tức là gần như phải biến nhà thành rừng."], "ordered": false}, {"type": "p", "text": "Nói ngắn gọn: cây có khả năng hấp thụ một phần chất ô nhiễm, nhưng **vài chậu cây trong phòng không thay thế được việc mở cửa thông gió hay máy lọc không khí**."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Snake_plant_Sansevieria_growing_in_a_pot_portrait.jpg/960px-Snake_plant_Sansevieria_growing_in_a_pot_portrait.jpg", "caption": "Lưỡi hổ trồng chậu — cây đẹp, bền, nhưng đừng kỳ vọng một chậu \"lọc sạch\" cả phòng."}, {"type": "h2", "text": "Còn chuyện \"lưỡi hổ nhả oxy ban đêm\"?"}, {"type": "p", "text": "Lưỡi hổ thuộc nhóm cây quang hợp kiểu CAM — mở khí khổng ban đêm để hấp thụ CO₂, giúp cây tiết kiệm nước. Đúng là cây \"hoạt động\" về đêm, nhưng lượng oxy vài chậu lưỡi hổ tạo ra **không đáng kể** so với thể tích phòng ngủ. Đặt lưỡi hổ phòng ngủ vì cây đẹp, ít chăm, đất khô không sinh muỗi — chứ không phải vì oxy."}, {"type": "h2", "text": "Vậy cây cảnh trong nhà mang lại lợi ích gì thật sự?"}, {"type": "p", "text": "Nhiều nghiên cứu về tâm lý học môi trường cho thấy những lợi ích rất thực:"}, {"type": "list", "items": ["**Cảm giác thư giãn, dễ chịu** khi nhìn thấy màu xanh; nhiều người thấy bớt căng thẳng khi làm việc cạnh cây.", "**Không gian đẹp hơn, \"sống\" hơn** — điều này ai cũng cảm nhận được.", "**Thói quen chăm sóc** một sinh vật sống, tốt cho tinh thần, nhất là với người lớn tuổi, trẻ nhỏ.", "**Tăng nhẹ độ ẩm** quanh cây — hữu ích trong phòng máy lạnh khô (nhưng cũng đừng kỳ vọng nhiều)."], "ordered": false}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Spathiphyllum_friedrichsthalii_%28Martinique%29_-_02.jpg/960px-Spathiphyllum_friedrichsthalii_%28Martinique%29_-_02.jpg", "caption": "Lan ý nở hoa — lợi ích thật của cây là làm không gian dễ chịu, đẹp mắt hơn."}, {"type": "h2", "text": "Muốn không khí trong nhà sạch hơn, nên làm gì?"}, {"type": "list", "items": ["**Mở cửa thông gió** mỗi ngày, nhất là sau khi nấu ăn, lau nhà bằng hóa chất, sơn sửa.", "**Dùng máy hút mùi** khi nấu nướng.", "**Hạn chế nguồn ô nhiễm**: nhang khói, thuốc lá trong nhà, nước xịt phòng, đồ nội thất mới nhiều mùi (để nơi thoáng vài tuần).", "**Dùng máy lọc không khí** có màng lọc phù hợp nếu sống gần đường lớn, khói bụi nhiều.", "**Trồng cây để làm đẹp, thư giãn** — kết hợp với các việc trên."], "ordered": true}, {"type": "note", "title": "Cây cũng có thể làm không khí kém hơn nếu chăm sai", "text": "Đất ẩm ướt liên tục, đĩa lót đọng nước có thể sinh nấm mốc, muỗi. Chăm đúng (tưới vừa đủ, đổ nước thừa) mới giữ được lợi ích của cây trong nhà."}, {"type": "h2", "text": "Chọn cây trong nhà thế nào cho hợp?"}, {"type": "p", "text": "Thay vì chọn theo danh sách \"lọc không khí\", hãy chọn theo **chỗ đặt và thời gian chăm** của bạn:"}, {"type": "table", "rows": [["Bạn có", "Cây hợp"], ["Góc thiếu sáng, ít thời gian", "Lưỡi hổ, bạch mã, vạn niên thanh"], ["Chỗ sáng tán xạ, chăm vừa phải", "Lan ý, phú quý, trầu bà đế vương"], ["Nhà có thú cưng", "Lan chi, đuôi công, dương xỉ"], ["Cửa sổ có nắng", "Ngọc bích, tùng thơm"]]}, {"type": "products", "title": "Cây trong nhà dễ chăm", "slugs": ["lan-chi", "luoi-ho", "lan-y", "duong-xi", "van-nien-thanh", "trau-ba-de-vuong-xanh"]}, {"type": "p", "text": "Tham khảo thêm: [cây trồng trong nhà thiếu sáng](/goc-cham-cay/cay-trong-nha-thieu-sang) và [cây đặt phòng ngủ](/goc-cham-cay/cay-dat-phong-ngu)."}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/KLXLJSBKJI.jpg', 4, '[]'::jsonb, '["lọc không khí", "nasa", "cây trong nhà", "sự thật"]'::jsonb, 'Cây cảnh có lọc không khí không? Sự thật về nghiên cứu NASA năm 1989, cần bao nhiêu cây, lợi ích thật của cây trong nhà và cách giữ không khí trong nhà sạch.'),
('bo-tri-cay-phong-khach-can-ho', 'Bố trí cây cho phòng khách, căn hộ chung cư: chọn cây chủ đạo, cây phụ và cách phối cho hài hòa', 'Phòng khách nhiều cây mà vẫn gọn, đẹp không phải nhờ mua thật nhiều, mà nhờ chọn đúng một cây chủ đạo, vài cây phụ và đặt đúng chỗ. Bài này hướng dẫn từng bước bố trí cây cho phòng khách căn hộ, kèm cách phối theo phong cách nội thất.', '[{"type": "p", "text": "Phòng khách là nơi cây xanh \"được nhìn\" nhiều nhất trong nhà. Nhưng cũng là nơi dễ rối nhất: mua mỗi lần một chậu, đặt mỗi chỗ một cây, lâu dần phòng như kho cây mà vẫn không đẹp. Bí quyết của những phòng khách nhiều cây mà vẫn gọn là **có bố cục**: một cây chủ đạo, vài cây phụ, và một điểm nhấn."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/TDAU1ERCD4.jpg", "caption": "Góc trang trí với chậu lan chi cạnh đồ decor — vài chậu đặt có chủ đích đẹp hơn nhiều chậu đặt rải rác."}, {"type": "h2", "text": "Bước 1: Xác định nguồn sáng của phòng khách"}, {"type": "p", "text": "Đứng giữa phòng khách và xem:"}, {"type": "list", "items": ["Cửa sổ, cửa ban công hướng nào? Có nắng chiếu vào giờ nào?", "Khu vực trong vòng **1–2m quanh cửa sổ** là chỗ sáng nhất — dành cho cây cần sáng (giống lá đỏ, lá vàng).", "Góc xa cửa sổ, cạnh tivi, cạnh cầu thang là chỗ thiếu sáng — dành cho cây chịu bóng."], "ordered": false}, {"type": "p", "text": "Căn hộ chung cư thường chỉ có một mặt kính lớn ra ban công, nên phần lớn cây sẽ tập trung ở nửa phòng gần ban công."}, {"type": "h2", "text": "Bước 2: Chọn một cây chủ đạo"}, {"type": "p", "text": "Cây chủ đạo là cây lớn nhất, đặt sàn, cao 70cm–1,5m, ở một góc phòng dễ nhìn thấy từ cửa ra vào hoặc sofa. Chỉ cần **một** cây chủ đạo cho phòng khách 15–25m²:"}, {"type": "list", "items": ["[Trầu bà đế vương đỏ](/san-pham/trau-ba-de-vuong-do) hoặc xanh loại 3 thân — lá to bóng, tán rộng, sang.", "[Dạ lan thanh](/san-pham/da-lan-thanh) cỡ 70cm–1m — xanh tốt quanh năm, chịu bóng, hợp góc xa cửa sổ.", "[Vạn niên thanh](/san-pham/van-nien-thanh) — lá loang trắng giúp góc tối sáng hơn."], "ordered": false}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09419.jpg/960px-Philodendron_erubescens_-_Begonia_House_-_Wellington_Botanic_Garden_-_Wellington%2C_NZ_-_DSC09419.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Lá trầu bà đỏ — cây chủ đạo lá to tạo điểm nhìn chính cho phòng khách."}, {"type": "h2", "text": "Bước 3: Thêm 2–3 cây phụ"}, {"type": "p", "text": "Cây phụ nhỏ hơn, đặt trên kệ tivi, bàn console, bàn trà, bệ cửa sổ — tạo nhịp điệu cho phòng:"}, {"type": "list", "items": ["**Trên kệ tivi**: [ngân hậu](/san-pham/ngan-hau), [phú quý](/san-pham/phu-quy) cỡ 30–50cm.", "**Bàn trà**: cây thấp dưới 30cm để không chắn tầm nhìn khi ngồi nói chuyện — [ngọc ngân](/san-pham/ngoc-ngan), [môn quan âm](/san-pham/mon-quan-am) cỡ nhỏ.", "**Bệ cửa sổ / cạnh ban công**: [tùng thơm](/san-pham/tung-thom), [ngọc bích](/san-pham/ngoc-bich) — cây cần sáng."], "ordered": false}, {"type": "h2", "text": "Bước 4: Một điểm nhấn trên cao"}, {"type": "p", "text": "Cây treo hoặc cây rủ trên kệ cao tạo chiều sâu cho phòng mà không chiếm sàn: [dương xỉ](/san-pham/duong-xi) giỏ treo cạnh cửa ban công, [lan chi](/san-pham/lan-chi) trên kệ sách. Căn hộ nhỏ đặc biệt nên tận dụng chiều cao thay vì đặt thêm chậu dưới sàn."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/JOHHVIOMIW.jpg", "caption": "Kệ tường xếp chậu cây — tận dụng chiều cao giúp căn hộ nhỏ có nhiều cây mà không chật."}, {"type": "h2", "text": "Phối cây theo phong cách nội thất"}, {"type": "table", "rows": [["Phong cách", "Cây hợp", "Chậu hợp"], ["Hiện đại, tối giản (trắng, xám)", "Lưỡi hổ, ngân hậu, bạch mã", "Chậu trắng, xám, xi măng trơn"], ["Ấm cúng, gỗ (nâu, be)", "Trầu bà đế vương xanh, dạ lan thanh, đuôi công", "Chậu đất nung, giỏ mây, gốm nâu"], ["Nhiệt đới, nhiều màu", "Trầu bà đế vương đỏ / vàng, môn quan âm", "Chậu gốm men màu"], ["Cổ điển, Á Đông", "Phú quý, vạn lộc, ngọc bích", "Chậu sứ men lam, gốm Bát Tràng"]]}, {"type": "h2", "text": "Những nguyên tắc nhỏ giúp phòng khách gọn đẹp"}, {"type": "list", "items": ["**Số lẻ trông tự nhiên hơn số chẵn**: cụm 3 chậu cao – vừa – thấp đẹp hơn 2 chậu bằng nhau đặt cạnh nhau.", "**Thống nhất chậu**: dùng 1–2 kiểu chậu (cùng màu hoặc cùng chất liệu) cho cả phòng.", "**Chừa lối đi ít nhất 80cm** — cây lá xòe đặt sát lối đi sẽ bị chạm, gãy lá.", "**Không đặt cây sát máy lạnh, tivi, loa** — gió lạnh làm cháy lá, nhiệt từ thiết bị làm lá khô.", "**Kê cây lớn lên đế có bánh xe** để dễ lau sàn và xoay chậu đón sáng đều.", "**Đổi vị trí cây phụ theo mùa** để phòng có cảm giác mới mà không cần mua thêm."], "ordered": true}, {"type": "note", "title": "Căn hộ hướng Tây nắng chiều gắt", "text": "Cây đặt sát kính ban công hướng Tây có thể cháy lá vào chiều mùa khô. Kéo rèm voan mỏng từ 14 giờ, hoặc lùi cây cách kính 1m. Xem thêm [cháy lá do nắng gắt](/benh-cay/chay-la-do-nang)."}, {"type": "products", "title": "Cây cho phòng khách", "slugs": ["trau-ba-de-vuong-do", "da-lan-thanh", "van-nien-thanh", "ngan-hau", "mon-quan-am", "lan-y-nu-hoang"]}, {"type": "p", "text": "Muốn có phương án chọn cây theo đúng diện tích, hướng nắng nhà bạn? Dùng [Tư vấn chọn cây](/tu-van-chon-cay) — chọn \"Trong nhà\", nhập diện tích, web sẽ gợi ý vị trí, số lượng và cây phù hợp."}]'::jsonb, 'https://cdn.stocksnap.io/img-thumbs/960w/TDAU1ERCD4.jpg', 4, '[]'::jsonb, '["phòng khách", "chung cư", "decor", "bố trí cây"]'::jsonb, 'Bố trí cây phòng khách căn hộ chung cư: chọn cây chủ đạo (trầu bà đế vương, dạ lan thanh), cây phụ, cây treo; cách phối theo phong cách nội thất và ánh sáng.')
) AS v(slug, title, excerpt, body, cover, minutes, diseases, tags, seo)
WHERE NOT EXISTS (SELECT 1 FROM "posts" p WHERE p."slug" = v.slug);
